logic/core.py:
"""Safe AST, deterministic source generation, and genuine verifier adapters.

The model has two independent Boolean variables: whether the tested door is
safe and whether the asked guard tells the truth. The other guard has the
opposite truthfulness. These are exactly the four relevant Two Guards worlds.
User/model text is metadata: it is never interpolated into executable code.
"""

from __future__ import annotations

import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import signal
import subprocess
import tempfile
import time
import threading
from dataclasses import dataclass
from typing import Any, Literal


class ClaimError(ValueError):
    """The claim is outside the supported, safe intermediate representation."""


@dataclass(frozen=True)
class Expr:
    op: Literal["const", "atom", "not", "and", "or", "implies", "iff", "answer"]
    value: bool | str | None = None
    children: tuple["Expr", ...] = ()

    def json(self) -> dict[str, Any]:
        if self.op == "const":
            return {"op": self.op, "value": self.value}
        if self.op == "atom":
            return {"op": self.op, "name": self.value}
        if self.op == "not":
            return {"op": self.op, "arg": self.children[0].json()}
        if self.op == "answer":
            return {"op": self.op, "guard": self.value,
                    "proposition": self.children[0].json()}
        return {"op": self.op, "left": self.children[0].json(),
                "right": self.children[1].json()}


@dataclass(frozen=True)
class Strategy:
    question: Expr
    on_no: str | None
    on_yes: str | None

    def json(self):
        return {"question": self.question.json(), "on_no": self.on_no, "on_yes": self.on_yes}


@dataclass(frozen=True)
class Claim:
    id: str
    kind: Literal["step", "solution"]
    text: str
    assumptions: tuple[Expr, ...]
    conclusion: Expr
    depends_on: tuple[str, ...]
    strategy: Strategy | None = None

    def json(self) -> dict[str, Any]:
        return {"id": self.id, "kind": self.kind, "text": self.text,
                "assumptions": [expr.json() for expr in self.assumptions],
                "conclusion": self.conclusion.json(),
                "depends_on": list(self.depends_on),
                "strategy": self.strategy.json() if self.strategy else None}


_SHAPES = {
    "const": {"op", "value"}, "atom": {"op", "name"},
    "not": {"op", "arg"}, "answer": {"op", "guard", "proposition"},
    **{op: {"op", "left", "right"} for op in ("and", "or", "implies", "iff")},
}
_IDENTIFIER = re.compile(r"^[A-Za-z][A-Za-z0-9_-]{0,63}$")
_WORLDS = tuple((safe, truthful) for safe in (False, True)
                for truthful in (False, True))


def _expr(data: Any, depth: int = 0, budget: list[int] | None = None) -> Expr:
    budget = budget if budget is not None else [128]
    budget[0] -= 1
    if depth > 12 or budget[0] < 0:
        raise ClaimError("An expression is too large; explain one smaller step.")
    if not isinstance(data, dict) or not isinstance(data.get("op"), str):
        raise ClaimError("Each expression must be an object with an op.")
    op = data["op"]
    if op not in _SHAPES or set(data) != _SHAPES[op]:
        raise ClaimError(f"Unsupported expression shape: {op!r}.")
    if op == "const":
        if type(data["value"]) is not bool:
            raise ClaimError("A Boolean constant must be true or false.")
        return Expr(op, data["value"])
    if op == "atom":
        if data["name"] not in ("safe", "truthful"):
            raise ClaimError("The supported atoms are safe and truthful.")
        return Expr(op, data["name"])
    if op == "not":
        return Expr(op, children=(_expr(data["arg"], depth + 1, budget),))
    if op == "answer":
        if data["guard"] not in ("asked", "other"):
            raise ClaimError("A guard must be asked or other.")
        return Expr(op, data["guard"],
                    (_expr(data["proposition"], depth + 1, budget),))
    return Expr(op, children=(_expr(data["left"], depth + 1, budget),
                             _expr(data["right"], depth + 1, budget)))


def validate_expr(data: Any) -> dict[str, Any]:
    """Validate and return a fresh normalized JSON expression."""
    return _expr(data).json()


def _claim(data: Any) -> Claim:
    if not isinstance(data, dict):
        raise ClaimError("A claim must be an object.")
    allowed = {"id", "kind", "text", "assumptions", "conclusion", "depends_on", "strategy"}
    if set(data) - allowed or "conclusion" not in data:
        raise ClaimError("A claim has unknown fields or lacks a conclusion.")
    claim_id = data.get("id", "candidate")
    if not isinstance(claim_id, str) or not _IDENTIFIER.fullmatch(claim_id):
        raise ClaimError("Claim IDs must be short letters/numbers with - or _.")
    kind = data.get("kind", "step")
    if kind not in ("step", "solution"):
        raise ClaimError("A claim kind must be step or solution.")
    text = data.get("text", "")
    if not isinstance(text, str) or len(text) > 8000:
        raise ClaimError("Claim text must be at most 8000 characters.")
    assumptions = data.get("assumptions", [])
    dependencies = data.get("depends_on", [])
    if not isinstance(assumptions, list) or len(assumptions) > 12:
        raise ClaimError("A step can have up to 12 assumptions.")
    if not isinstance(dependencies, list) or len(dependencies) > 32:
        raise ClaimError("A step can cite up to 32 earlier claims.")
    if any(not isinstance(d, str) or not _IDENTIFIER.fullmatch(d) for d in dependencies):
        raise ClaimError("A dependency must be a valid claim ID.")
    if len(set(dependencies)) != len(dependencies) or claim_id in dependencies:
        raise ClaimError("Dependencies must be distinct earlier claims.")
    budget = [256]
    parsed_assumptions = tuple(_expr(a, budget=budget) for a in assumptions)
    conclusion = _expr(data["conclusion"], budget=budget)
    # A guard case may be phrased in the conclusion instead of the assumption
    # list. Move that exact condition without changing the logical statement.
    truthful = Expr("atom", "truthful")
    guard_conditions = (truthful, Expr("not", children=(truthful,)))
    while conclusion.op == "implies" and conclusion.children[0] in guard_conditions:
        parsed_assumptions += (conclusion.children[0],)
        conclusion = conclusion.children[1]
    if len(parsed_assumptions) > 12:
        raise ClaimError("A normalized step can have up to 12 assumptions.")
    strategy = None
    raw_strategy = data.get("strategy")
    if raw_strategy is not None:
        if not isinstance(raw_strategy, dict) or set(raw_strategy) != {"question", "on_no", "on_yes"}:
            raise ClaimError("A strategy needs its question and both answer branches.")
        question = _expr(raw_strategy["question"], budget=budget)
        if question.op != "answer" or question.value != "asked":
            raise ClaimError("A strategy must identify the question I ask.")
        for branch in ("on_no", "on_yes"):
            if raw_strategy[branch] not in (None, "tested", "other"):
                raise ClaimError("A door choice must be tested, other, or unspecified.")
        if raw_strategy["on_no"] is None and raw_strategy["on_yes"] is None:
            raise ClaimError("A strategy must state at least one door choice.")
        strategy = Strategy(question, raw_strategy["on_no"], raw_strategy["on_yes"])
    return Claim(claim_id, kind, text, parsed_assumptions, conclusion,
                 tuple(dependencies), strategy)


def parse_claim(data: Any) -> dict[str, Any]:
    """Validate a claim. Missing optional fields receive stable defaults."""
    return _claim(data).json()


validate_claim = parse_claim


def _render(expr: Expr) -> str:
    if expr.op == "atom":
        return {"safe": "the tested door is safe",
                "truthful": "the asked guard tells the truth"}[expr.value]
    if expr.op == "const":
        return "true" if expr.value else "false"
    if expr.op == "not":
        return f"not ({_render(expr.children[0])})"
    if expr.op == "answer":
        guard = "asked guard" if expr.value == "asked" else "other guard"
        return f'the {guard} answers yes to “{_render(expr.children[0])}”'
    left, right = map(_render, expr.children)
    if expr.op == "implies":
        return f"if ({left}), then ({right})"
    operator = {"and": "and", "or": "or", "iff": "exactly when"}[expr.op]
    return f"({left}) {operator} ({right})"


def render_expr(data: Any) -> str:
    return _render(_expr(data))


expression_to_text = render_expr


def render_claim(data: Any) -> str:
    claim = _claim(data)
    conclusion = _render(claim.conclusion)
    if claim.strategy:
        choices = []
        for answer, choice in (("yes", claim.strategy.on_yes), ("no", claim.strategy.on_no)):
            if choice is not None:
                choices.append(f"after {answer}, I go through the {choice} door")
        rule = "I ask whether " + _render(claim.strategy.question.children[0]) + "; " + "; ".join(choices)
        conclusion = rule if claim.conclusion == Expr("const", True) else conclusion + ". " + rule
    if claim.assumptions:
        return "Assuming " + " and ".join(_render(a) for a in claim.assumptions) + ", " + conclusion + "."
    return conclusion[0].upper() + conclusion[1:] + "."


def _and(expressions: tuple[Expr, ...]) -> Expr:
    result = Expr("const", True)
    for expression in reversed(expressions):
        result = Expr("and", children=(expression, result))
    return result


def _theorem(claim: Claim) -> Expr:
    # Preserve conditional claims as implications at every dependency edge.
    return Expr("implies", children=(_and(claim.assumptions), _conclusion(claim)))


def _conclusion(claim: Claim) -> Expr:
    """Verify declared actions as well as the descriptive claim."""
    expressions = [claim.conclusion]
    if claim.strategy:
        for answer, choice in ((False, claim.strategy.on_no), (True, claim.strategy.on_yes)):
            if choice is None:
                continue
            condition = claim.strategy.question if answer else Expr("not", children=(claim.strategy.question,))
            safe = Expr("atom", "safe")
            chosen_safe = safe if choice == "tested" else Expr("not", children=(safe,))
            expressions.append(Expr("implies", children=(condition, chosen_safe)))
    return _and(tuple(expressions)) if claim.strategy else claim.conclusion


def _dependencies(claim: Claim, accepted: list[dict[str, Any]]) -> list[Claim]:
    if len(accepted) > 128:
        raise ClaimError("This prototype supports up to 128 accepted steps.")
    by_id: dict[str, Claim] = {}
    for raw in accepted:
        # Caller supplies trusted, server-owned accepted state, not browser state.
        item = _claim(raw)
        if item.id in by_id:
            raise ClaimError("Accepted claim IDs are not unique.")
        by_id[item.id] = item
    ordered: list[Claim] = []
    visiting: set[str] = set()
    visited: set[str] = set()

    def visit(claim_id: str) -> None:
        if claim_id in visiting:
            raise ClaimError("The argument graph contains a cycle.")
        if claim_id in visited:
            return
        if claim_id not in by_id:
            raise ClaimError(f"Dependency {claim_id!r} has not been accepted.")
        item = by_id[claim_id]
        visiting.add(claim_id)
        for dependency in item.depends_on:
            visit(dependency)
        visiting.remove(claim_id)
        visited.add(claim_id)
        ordered.append(item)

    for dependency in claim.depends_on:
        visit(dependency)
    return ordered


def _prolog(expr: Expr) -> str:
    if expr.op == "const":
        return "true" if expr.value else "false"
    if expr.op == "atom":
        return str(expr.value)
    if expr.op == "answer":
        return f"answer({expr.value},{_prolog(expr.children[0])})"
    return f"{expr.op}({','.join(_prolog(c) for c in expr.children)})"


_PROLOG_PREAMBLE = r"""% Generated from a validated finite Boolean AST, never raw model code.
:- use_module(library(http/json)).
bool(false).
bool(true).
neg(false,true).
neg(true,false).
eval(true,_,_,true).
eval(false,_,_,false).
eval(safe,S,_,S).
eval(truthful,_,T,T).
eval(not(P),S,T,V) :- eval(P,S,T,A), neg(A,V).
eval(and(P,Q),S,T,V) :- eval(P,S,T,A), eval(Q,S,T,B),
    (A==true, B==true -> V=true ; V=false).
eval(or(P,Q),S,T,V) :- eval(P,S,T,A), eval(Q,S,T,B),
    (A==true -> V=true ; B==true -> V=true ; V=false).
eval(implies(P,Q),S,T,V) :- eval(P,S,T,A), eval(Q,S,T,B),
    (A==false -> V=true ; V=B).
eval(iff(P,Q),S,T,V) :- eval(P,S,T,A), eval(Q,S,T,B),
    (A==B -> V=true ; V=false).
eval(answer(asked,P),S,T,V) :- eval(P,S,T,A),
    (T==true -> V=A ; neg(A,V)).
eval(answer(other,P),S,T,V) :- eval(P,S,T,A),
    (T==false -> V=A ; neg(A,V)).
world(S,T) :- bool(S), bool(T).
holds_all([],_,_).
holds_all([H|R],S,T) :- eval(H,S,T,true), holds_all(R,S,T).
dependency_failure(I,S,T) :- dependency(I,P), world(S,T), eval(P,S,T,false).
"""

# Evaluate each ground Boolean proposition with iterative deepening DFS. The
# requested truth value is unified only AFTER a complete evaluation; a cutoff
# can therefore never masquerade as a false proposition inside negation/forall.
_start = _PROLOG_PREAMBLE.index("eval(true")
_end = _PROLOG_PREAMBLE.index("world(S,T)")
_PROLOG_PREAMBLE = (_PROLOG_PREAMBLE[:_start]
    + _PROLOG_PREAMBLE[_start:_end].replace("eval(", "eval_dfs(")
    + r'''
% Recursive evaluator search uses IDDFS, restarting at increasing bounds.
eval(E,S,T,Expected) :- eval_iddfs(E,S,T,1,Value), Expected=Value.
eval_iddfs(E,S,T,Limit,Value) :-
    call_with_depth_limit(eval_dfs(E,S,T,Found),Limit,Result),
    ( Result == depth_limit_exceeded ->
        Next is Limit+1,
        (Next =< 512 -> eval_iddfs(E,S,T,Next,Value)
         ; throw(error(search_depth_exhausted,eval/4)))
    ; Value=Found ).
'''+ _PROLOG_PREAMBLE[_end:])


def _prolog_source(claim: Claim, dependencies: list[Claim]) -> str:
    deps = "\n".join(f"dependency({i},{_prolog(_theorem(d))})."
                     for i, d in enumerate(dependencies))
    if not dependencies:
        deps = "dependency(_,_) :- fail."
    assumptions = "[" + ",".join(_prolog(a) for a in claim.assumptions) + "]"
    return _PROLOG_PREAMBLE + deps + rf"""
assumptions({assumptions}).
conclusion({_prolog(_conclusion(claim))}).
main :-
    assumptions(As), conclusion(C),
    ( dependency_failure(I,S,T) ->
        json_write_dict(current_output, _{{status:invalid_dependency,dependency:I,safe:S,truthful:T}})
    ; \+ (world(S,T), holds_all(As,S,T)) ->
        json_write_dict(current_output, _{{status:invalid_assumptions}})
    ; (world(S,T), holds_all(As,S,T), eval(C,S,T,false)) ->
        json_write_dict(current_output, _{{status:refuted,safe:S,truthful:T}})
    ; findall(1,(world(S,T), holds_all(As,S,T)), Cases), length(Cases,Count),
        json_write_dict(current_output, _{{status:verified,checked_worlds:Count}})
    ), nl.
:- initialization(main, main).
"""


def _isabelle(expr: Expr) -> str:
    if expr.op == "atom":
        return str(expr.value)
    if expr.op == "const":
        return "True" if expr.value else "False"
    if expr.op == "not":
        return f"(\\<not> {_isabelle(expr.children[0])})"
    if expr.op == "answer":
        guard = "truthful" if expr.value == "asked" else "(\\<not> truthful)"
        return f"(guard_answer {guard} {_isabelle(expr.children[0])})"
    symbol = {"and": "\\<and>", "or": "\\<or>", "implies": "\\<longrightarrow>", "iff": "="}[expr.op]
    return f"({_isabelle(expr.children[0])} {symbol} {_isabelle(expr.children[1])})"


def _isabelle_source(claim: Claim, dependencies: list[Claim]) -> tuple[str, str]:
    theory = """theory Checked_Argument
  imports Main
begin

definition guard_answer :: "bool => bool => bool" where
  "guard_answer truthful proposition = (if truthful then proposition else (\\<not> proposition))"

"""
    for i, item in enumerate([*dependencies, claim]):
        name = f"dependency_{i}" if i < len(dependencies) else "checked_step"
        theory += (f"lemma {name}:\n  fixes safe truthful :: bool\n"
                   f'  shows "{_isabelle(_theorem(item))}"\n'
                   "  by (cases safe; cases truthful; simp add: guard_answer_def)\n\n")
    theory += "end\n"
    digest = hashlib.sha256(theory.encode("utf-8")).hexdigest()[:16]
    root = (f"session HE_Tech_{digest} = HOL +\n"
            "  options [document = false, quick_and_dirty = false]\n"
            "  theories Checked_Argument\n")
    return theory, root


def _command(value: Any, label: str) -> list[str] | None:
    if value in (None, "", []):
        return None
    if isinstance(value, str):
        # A string is an executable path, not a command to parse with a shell.
        value = [value]
    if not isinstance(value, list) or not all(isinstance(p, str) and p and "\x00" not in p for p in value):
        raise ClaimError(f"{label} must be an executable path or an argv list.")
    return value[:]


def resolve_commands(config: dict[str, Any] | None = None) -> dict[str, list[str] | None]:
    config = config or {}
    swipl = config.get("swipl_command") or os.environ.get("SWIPL_COMMAND") or shutil.which("swipl")
    if not swipl:
        candidate = Path(r"C:\Program Files\swipl\bin\swipl.exe")
        if candidate.is_file():
            swipl = str(candidate)
    isabelle = config.get("isabelle_command") or os.environ.get("ISABELLE_COMMAND") or shutil.which("isabelle")
    return {"prolog": _command(swipl, "swipl_command"),
            "isabelle": _command(isabelle, "isabelle_command")}


def _result(status: str, detail: str, **extra: Any) -> dict[str, Any]:
    return {"status": status, "detail": detail, "message": detail, **extra}


def _run(argv: list[str], cwd: Path, timeout: float) -> tuple[subprocess.CompletedProcess[str] | None, dict[str, Any] | None]:
    started = time.monotonic()
    process = None
    try:
        process = subprocess.Popen(argv, cwd=str(cwd), text=True, encoding="utf-8",
                                   errors="replace", stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                   shell=False, start_new_session=os.name != "nt",
                                   creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0) | (getattr(subprocess, "BELOW_NORMAL_PRIORITY_CLASS", 0) if threading.current_thread().name.startswith("anticipation") else 0))
        stdout, stderr = process.communicate(timeout=timeout)
        completed = subprocess.CompletedProcess(argv, process.returncode, stdout, stderr)
        return completed, None
    except FileNotFoundError:
        return None, _result("unavailable", "The configured executable could not be found.")
    except subprocess.TimeoutExpired as exc:
        if process is not None and process.poll() is None:
            try:
                if os.name == "nt":
                    subprocess.run(["taskkill", "/PID", str(process.pid), "/T", "/F"],
                                   capture_output=True, timeout=10,
                                   creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
                else:
                    os.killpg(process.pid, signal.SIGKILL)
            except (OSError, subprocess.TimeoutExpired):
                process.kill()
            try:
                process.communicate(timeout=5)
            except subprocess.TimeoutExpired:
                process.kill()
        return None, _result("timeout", f"Verification exceeded {timeout:g} seconds.",
                             elapsed_seconds=round(time.monotonic() - started, 3),
                             log=((exc.stdout or b'').decode('utf-8',errors='replace') if isinstance(exc.stdout,bytes) else (exc.stdout or ''))[-10000:])
    except OSError as exc:
        return None, _result("error", f"The verifier could not start: {exc}")


def _run_prolog(command: list[str] | None, directory: Path, timeout: float) -> dict[str, Any]:
    if command is None:
        return _result("unavailable", "SWI-Prolog is not configured or installed.")
    completed, error = _run([*command, "-q", "-s", "check.pl"], directory, timeout)
    if error:
        return error
    if completed.returncode:
        return _result("error", "SWI-Prolog did not complete the check.",
                       exit_code=completed.returncode, log=(completed.stdout + completed.stderr)[-10000:])
    try:
        payload = json.loads(completed.stdout)
    except (ValueError, TypeError):
        return _result("error", "SWI-Prolog returned an unexpected response.", log=completed.stdout[-10000:])
    if not isinstance(payload, dict) or payload.get("status") not in {
            "verified", "refuted", "invalid_assumptions", "invalid_dependency"}:
        return _result("error", "SWI-Prolog returned an unknown verification result.")
    status = payload["status"]
    details = {"verified": "The claim holds in every applicable model world.",
               "refuted": "A model world contradicts the claim.",
               "invalid_assumptions": "No model world satisfies all these assumptions.",
               "invalid_dependency": "A cited earlier claim is not valid in the model."}
    return _result(status, details[status], **{k: v for k, v in payload.items() if k != "status"})


def _run_isabelle(command: list[str] | None, directory: Path, timeout: float) -> dict[str, Any]:
    if command is None:
        return _result("unavailable", "Isabelle/HOL is not configured or installed.")
    # A relative -D argument also works when argv invokes Cygwin bash and a
    # Windows pathname would otherwise be interpreted using POSIX semantics.
    completed, error = _run([*command, "build", "-D", ".", "-o", f"timeout={max(10,timeout-40):g}", "-o", "document=false",
                             "-o", "quick_and_dirty=false"], directory, timeout)
    if error:
        return error
    log = (completed.stdout + completed.stderr)[-12000:]
    if completed.returncode:
        return _result("unproven", "Isabelle did not produce a completed proof. Inspect the build log.",
                       exit_code=completed.returncode, log=log)
    return _result("verified", "Isabelle/HOL completed the generated theory with checked proofs.", log=log)


def verify_claim(claim: dict[str, Any], accepted_claims: list[dict[str, Any]] | None = None,
                 config: dict[str, Any] | None = None) -> dict[str, Any]:
    """Generate and execute both checks; never substitute an internal proof.

    ``accepted_claims`` must come from trusted server state. Commands are admin
    configuration, never a request parameter. They are argv lists run without a
    shell, e.g. ["C:/Isabelle/contrib/cygwin/bin/bash.exe", ".../bin/isabelle"].
    """
    config = config or {}
    parsed = _claim(claim)
    dependencies = _dependencies(parsed, accepted_claims or [])
    prolog_source = _prolog_source(parsed, dependencies)
    isabelle_source, root = _isabelle_source(parsed, dependencies)
    commands = resolve_commands(config)
    timeout = float(config.get("timeout", 120))
    isabelle_timeout = float(config.get("isabelle_timeout", timeout))
    if timeout <= 0 or timeout > 1800 or isabelle_timeout <= 0 or isabelle_timeout > 1800:
        raise ClaimError("The timeout must be between 0 and 1800 seconds.")
    output_root = config.get("work_dir")
    if output_root:
        Path(output_root).mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix="hetech-proof-", dir=output_root, ignore_cleanup_errors=True) as temp:
        directory = Path(temp)
        (directory / "check.pl").write_text(prolog_source, encoding="utf-8")
        (directory / "Checked_Argument.thy").write_text(isabelle_source, encoding="utf-8")
        (directory / "ROOT").write_text(root, encoding="utf-8")
        prolog = _run_prolog(commands["prolog"], directory, min(timeout, 30))
        if prolog["status"] in ("refuted", "invalid_assumptions", "invalid_dependency"):
            isabelle = _result("skipped", "No proof requested because Prolog found a contradiction or invalid assumptions.")
        else:
            isabelle = _run_isabelle(commands["isabelle"], directory, isabelle_timeout)
    prolog_status = prolog["status"]
    isabelle_status = isabelle["status"]
    if prolog_status == "refuted":
        status = "refuted"
    elif prolog_status == "invalid_assumptions":
        status = "invalid_assumptions"
    elif prolog_status == "verified" and isabelle_status == "verified":
        # Pedagogical prompts are advisory. Goal discovery is independently
        # checked over the whole confirmed graph after every verification.
        status = "verified"
    elif "unavailable" in (prolog_status, isabelle_status):
        status = "unavailable"
    else:
        status = "error"
    counterexample = None
    if prolog_status == "refuted":
        counterexample = {"safe": prolog["safe"], "truthful": prolog["truthful"],
                          "detail": ("The tested door is " + ("safe" if prolog["safe"] else "unsafe") +
                                     ", and the asked guard is the " + ("truth-teller" if prolog["truthful"] else "liar") + "."),
                          "source": "SWI-Prolog"}
    return {"status": status, "claim": parsed.json(), "rendered": render_claim(parsed.json()),
            "graph": {"kind": "Boolean argument graph", "candidate": parsed.json(),
                      "dependencies": [d.json() for d in dependencies],
                      "effective_theorem": _theorem(parsed).json(),
                      "search": "Iterative deepening DFS over Boolean expression evaluation; four finite worlds"},
            "engines": {"prolog": prolog, "isabelle": isabelle},
            "counterexample": counterexample,
            "sources": {"prolog": prolog_source, "isabelle": isabelle_source, "root": root}}

logic/theory.py:
"""Finite named-proposition adapter, with Prolog IDDFS and original HOL proofs."""
from __future__ import annotations
import hashlib
import json
import re
from pathlib import Path
import tempfile
from .core import ClaimError, _result, _run, _run_isabelle, resolve_commands
from . import learner

def parse_claim(raw, scenario):
    nodes = scenario["nodes"]
    def literals(items):
        if not isinstance(items,list) or len(items)>12: raise ClaimError("Use at most twelve propositions in a step.")
        out=[]
        for item in items:
            if not isinstance(item,dict) or set(item)!={"id","positive"} or item["id"] not in nodes or type(item["positive"]) is not bool:
                raise ClaimError("A proposition must belong to this scenario.")
            if item not in out: out.append(item.copy())
        return out
    conclusions=literals(raw.get("conclusions"))
    if not conclusions: raise ClaimError("State at least one conclusion.")
    deps=raw.get("depends_on",[])
    if not isinstance(deps,list) or len(deps)>32 or any(not isinstance(d,str) for d in deps): raise ClaimError("Invalid dependencies.")
    text=raw.get("text","")
    if not isinstance(text,str) or len(text)>8000: raise ClaimError("Invalid claim text.")
    assumptions=literals(raw.get('assumptions',[]));reasoning_mode=learner.mode(raw)
    from nlp_vocabulary import named_reference_info
    try:references=named_reference_info(text,scenario)
    except ValueError as exc:raise ClaimError(str(exc)) from exc
    if 'rules_used' in raw and raw['rules_used']!=references['rules_used']:raise ClaimError('Rule citations must match the original thought.')
    if raw.get('mode','assertion')=='assertion':
        reasoning_mode=learner.mode({k:v for k,v in raw.items() if k!='mode'})
        from nlp_vocabulary import exact_reason_vocabulary
        vocabulary=[dict(id=p,meaning=n['label']) for p,n in nodes.items()]
        for entry in references['facts']:next(v for v in vocabulary if v['id']==entry['id']).setdefault('references',[]).append(entry['reference'])
        anchored=exact_reason_vocabulary(references['surface'],vocabulary)
        if anchored and all(p['positive'] for p in assumptions+conclusions) and set(anchored['assumptions'])=={p['id'] for p in assumptions} and set(anchored['conclusions'])=={p['id'] for p in conclusions}:
            reasoning_mode='assertion'
    return dict(id=raw["id"],kind="step",domain="theory",text=text,conclusions=conclusions,assumptions=assumptions,depends_on=deps,mode=reasoning_mode,**({'rules_used':references['rules_used']} if references['rules_used'] else {}))

def label(literal, scenario):
    text=scenario["nodes"][literal["id"]]["label"]
    return text if literal["positive"] else "It is not the case that "+text

def view(claim, scenario):
    conclusion="; ".join(label(p,scenario) for p in claim["conclusions"])
    from nlp_vocabulary import named_reference_info
    try:cited_rules=[r['reference'] for r in named_reference_info(claim['text'],scenario)['rules']]
    except ValueError:cited_rules=['Unrecognised citation; I can revisit this step']
    return dict(id=claim["id"],kind=claim["kind"],text=claim["text"],summary=conclusion,conclusion=conclusion,assumptions=[label(p,scenario) for p in claim["assumptions"]],dependencies=claim["depends_on"],strategy=None,graph=claim,**({'cited_rules':cited_rules} if cited_rules else {}))

def relevant_projection(claim, scenario):
    wanted={p['id'] for p in claim['assumptions']+claim['conclusions']}
    terms={" ".join(n['hol'].split()):p for p,n in scenario['nodes'].items()}
    changed=True
    while changed:
        before=len(wanted)
        for term,p in terms.items():
            if term.startswith(r"\<not> ") and term[7:] in terms:
                q=terms[term[7:]]
                if p in wanted or q in wanted:wanted.update([p,q])
        for r in scenario['rules']:
            if r['conclusion'] in wanted:wanted.update(r['premises'])
        changed=len(wanted)!=before
    return wanted

def prolog_source(claim, scenario):
    nodes=scenario["nodes"]
    wanted=relevant_projection(claim,scenario)
    ids={p:"a"+str(i) for i,p in enumerate(nodes)}
    def atom(lit): return ("pos" if lit["positive"] else "neg")+"("+ids[lit["id"]]+")"
    lines=[":- use_module(library(http/json)).", ":- discontiguous fact/1, rule/3.", "fact(_) :- fail.", "rule(_,_,_) :- fail."]
    for p,n in nodes.items():
        if p in wanted and n["fact"]: lines.append(f"fact(pos({ids[p]})).")
    for i,r in enumerate(scenario["rules"]):
        if r["conclusion"] not in wanted:continue
        premises=','.join("pos("+ids[p]+")" for p in r["premises"])
        lines.append(f"rule(r{i},pos({ids[r['conclusion']]}),[{premises}]).")
    # An explicit negative proposition can establish the complement of another
    # named proposition. Absence of a derivation is never treated as negation.
    terms={" ".join(n["hol"].split()):p for p,n in nodes.items()}
    for term,p in terms.items():
        if p in wanted and term.startswith(r"\<not> ") and term[7:] in terms:
            q=terms[term[7:]]
            lines += [f"rule(negative_{ids[p]},neg({ids[q]}),[pos({ids[p]})]).",f"rule(negative_{ids[q]},neg({ids[p]}),[pos({ids[q]})])."]
    for p in scenario.get('_negative_roots',[]):
        lines.append(f"fact(neg({ids[p]})).")
    goals=','.join(atom(p) for p in (claim["conclusions"] if scenario.get('_learner_scope') else claim["assumptions"]+claim["conclusions"]))
    lines += [f"max_depth({len(nodes)*2+1}).",f"goals([{goals}])."]
    lines.append(r'''
% Iterative deepening DFS. Every rule edge consumes one depth unit. Each
% bound is exhausted by Prolog backtracking before the next is tried.
% A shortest proof never repeats a ground literal along a branch, so twice
% the proposition count is a complete bound for this finite Horn projection.
prove(A,_,_,_{kind:fact,atom:Text}) :- fact(A), term_string(A,Text).
prove(A,D,Path,_{kind:rule,rule:R,atom:Text,premises:Trees}) :-
    D > 0, \+ memberchk(A,Path), rule(R,A,Premises), D1 is D-1,
    prove_all(Premises,D1,[A|Path],Trees), term_string(A,Text).
prove_all([],_,_,[]).
prove_all([A|As],D,Path,[T|Ts]) :- prove(A,D,Path,T), prove_all(As,D,Path,Ts).
iddfs(Goals,Depth,Trace) :- max_depth(Max), between(0,Max,Depth),
    once(prove_all(Goals,Depth,[],Trace)), !.
opposite(pos(A),neg(A)).
opposite(neg(A),pos(A)).
main :- goals(Goals),
    ( iddfs(Goals,D,Trace) -> Result=_{status:verified,depth:D,trace:Trace}
    ; member(G,Goals), opposite(G,O), iddfs([O],D,Trace) ->
      term_string(G,Failed), Result=_{status:refuted,depth:D,trace:Trace,failed:Failed}
    ; Result=_{status:unsupported,detail:"No derivation in the finite projection; this is not a proof of falsehood."}
    ), put_dict(search,Result,"iterative deepening depth-first search",Output),
    json_write_dict(current_output,Output), nl.
:- initialization(main, main).
''')
    return '\n'.join(lines), {v:p for p,v in ids.items() if p in wanted}

def hol_source(claim, scenario):
    nodes=scenario["nodes"]
    literals=claim["conclusions"] if scenario.get('_learner_scope') else claim["assumptions"]+claim["conclusions"]
    if scenario.get("custom"):
        names={p:"v"+str(i) for i,p in enumerate(nodes)}
        def term(lit): return names[lit["id"]] if lit["positive"] else r"(\<not> "+names[lit["id"]]+")"
        premises=[names[p] for p,n in nodes.items() if n["fact"]]
        premises += [r"(\<not> "+names[p]+")" for p in scenario.get('_negative_roots',[])]
        premises += ["("+r" \<and> ".join(names[p] for p in r["premises"])+r") \<longrightarrow> "+names[r["conclusion"]] for r in scenario["rules"]]
        source='theory Checked_Argument imports Main begin\nlemma checked_step:\n  fixes '+" ".join(names.values())+' :: bool\n'
        if premises: source += '  assumes '+ '\n      and '.join('"'+p+'"' for p in premises)+'\n'
        source += '  shows "'+r" \<and> ".join('('+term(p)+')' for p in literals)+'"\n'
        source += ('  using assms\n' if premises else '')+'  by blast\nend\n'
    else:
        source=f'theory Checked_Argument imports {scenario["file"]} begin\n'
        if scenario.get("locale"): source += 'context '+scenario["locale"]+' begin\n'
        def term(lit):
            prop=nodes[lit["id"]]["hol"]
            return '('+prop+')' if lit["positive"] else r'(\<not> ('+prop+'))'
        source += 'lemma checked_step: "'+r" \<and> ".join(term(p) for p in literals)+'"\n'
        # Check against the problem preamble itself, not saved author lemmas.
        facts=[n['name'] for n in nodes.values() if n.get('origin')=='problem assumption']
        if facts:source+='  using '+" ".join(facts)+'\n'
        definitions=re.findall(r'(?m)^definition\s+(\w+)',scenario['source_text'])
        source+='  by (auto simp: '+" ".join(name+'_def' for name in definitions)+')\n'
        if scenario.get("locale"): source += 'end\n'
        source += 'end\n'
    digest=hashlib.sha256((source+scenario["source_hash"]).encode()).hexdigest()[:16]
    root=f'session Thread_Theory_{digest} = HOL +\n  options [document = false, quick_and_dirty = false]\n  theories Checked_Argument\n'
    return source,root

def verify_claim(claim, accepted, config, scenario):
    claim=parse_claim(claim,scenario)
    if not set(claim["depends_on"]) <= {c["id"] for c in accepted}: raise ClaimError("Cite accepted steps only.")
    context=learner.context(claim,accepted,scenario)
    pl,ids=prolog_source(claim,context['scenario'])
    thy,root=hol_source(claim,context['scenario'])
    commands=resolve_commands(config)
    prolog=_result("unavailable","SWI-Prolog is not configured.")
    with tempfile.TemporaryDirectory(prefix="thread-theory-", ignore_cleanup_errors=True) as temp:
        directory=Path(temp)
        (directory/"check.pl").write_text(pl,encoding="utf-8")
        (directory/"Checked_Argument.thy").write_text(thy,encoding="utf-8")
        (directory/"ROOT").write_text(root,encoding="utf-8")
        if not scenario.get("custom"):
            (directory/scenario["source_name"]).write_text(scenario["source_text"],encoding="utf-8")
        if commands["prolog"]:
            done,error=_run([*commands["prolog"],"-q","-s","check.pl"],directory,float(config.get("timeout",30)))
            if error: prolog=error
            elif done.returncode: prolog=_result("error","Prolog did not complete.",log=done.stderr[-10000:])
            else:
                try:
                    payload=json.loads(done.stdout)
                    status=payload.pop("status")
                    prolog=_result(status,"Finite Horn search completed using iterative deepening DFS.",**payload)
                except (ValueError,KeyError): prolog=_result("error","Unreadable Prolog result.")
        isabelle=_run_isabelle(commands["isabelle"],directory,float(config.get("isabelle_timeout",180))) if prolog["status"]=="verified" else _result("not_requested","A positive Prolog derivation is needed before certification.")
    status=prolog["status"]
    if status=="verified" and isabelle["status"]!="verified": status="unavailable" if isabelle["status"]=="unavailable" else "error"
    return dict(status=status,engines={"prolog":prolog,"isabelle":isabelle},sources={"prolog":pl,"isabelle":thy,"root":root,"imported_theory":scenario["source_text"]},graph=dict(kind="named-proposition graph",candidate=claim,epistemic={k:v for k,v in context.items() if k!='scenario'},nodes=[n for p,n in scenario["nodes"].items() if p in ids.values()],rules=[r for r in scenario["rules"] if r["conclusion"] in ids.values()],trace=prolog.get("trace",[]),prolog_atom_map=ids,accepted=accepted),counterexample={"detail":"The opposite of a stated proposition has a derivation in this case. I can inspect its proof tree below."} if status=="refuted" else None)

def goal_progress(accepted, scenario):
    learned=set()
    established=[]
    for c in accepted:
        if 'fact' in next(iter(scenario['nodes'].values()),{}):
            context=learner.context(c,established,scenario)
            if not context['grounded']: continue
        established.append(c)
        for lit in c["conclusions"]:
            if lit["positive"]: learned.update(scenario["nodes"][lit["id"]]["covers"])
    if scenario.get('challenge'):
        requirements=scenario['challenge']['requirements']
        # A compact decision with explicit supporting premises can meet the
        # warrant obligation without a separately worded intermediate claim.
        # This records coverage only; it never inserts an accepted graph node.
        for r in requirements:
            for route in r.get('support_routes',[]):
                for c in established:
                    conclusions={p['id'] for p in c['conclusions'] if p['positive']}
                    premises={p['id'] for p in c['assumptions'] if p['positive']}
                    if route['decision'] in conclusions and set(route['premises'])<=premises:
                        learned.add(route['warrant'])
        missing=[r['label'] for r in requirements if not set(r['any_of'])&learned]
        targets=list(dict.fromkeys(next(p for p in r['any_of'] if p in learned) for r in requirements if set(r['any_of'])&learned))
    else:
        targets=scenario['targets']
        missing=[p for p in targets if p not in learned]
    return learned,missing,targets

def check_solution(accepted, config, scenario):
    learned,missing,targets=goal_progress(accepted,scenario)
    result=dict(status="not_discovered",theorem=scenario["goal"],detail="I have not yet established every part of the scenario goal.",witness=None,engines={},sources={},graph={"targets":scenario["targets"],"learned":sorted(learned),"missing":missing})
    if missing: return result
    claim=dict(id="goal",text="Scenario goal",conclusions=[dict(id=p,positive=True) for p in targets],assumptions=[],depends_on=[c['id'] for c in accepted if 'fact' not in next(iter(scenario['nodes'].values()),{}) or learner.context(c,accepted[:accepted.index(c)],scenario)['grounded']])
    checked=verify_claim(claim,accepted,config,scenario)
    result.update(engines=checked["engines"],sources=checked["sources"],graph=checked["graph"])
    if checked["status"]=="verified":
        result.update(status="discovered",detail="My confirmed claims cover every goal and follow from the supplied scenario.",witness={"conclusions":[scenario["nodes"][p]["label"] for p in targets],"supporting_claims":[c["id"] for c in accepted]})
    else: result.update(status="error",detail="The goal still needs certification by both systems.")
    return result

logic/learner.py:
"""Pure epistemic bookkeeping; proof engines still certify every accepted step.

Scenario givens constrain the world. A learner's hypothetical premises never
change those givens or become established merely because a conditional is valid.
"""
import copy
import re

def rule_scope(claim,scenario):
    from nlp_vocabulary import named_reference_info
    try:selected=named_reference_info(claim.get('text',''),scenario)['rules_used']
    except ValueError:return {**scenario,'rules':[],'_invalid_citations':True}
    if 'rules_used' in claim and claim['rules_used']!=selected:return {**scenario,'rules':[],'_invalid_citations':True}
    if not selected:return scenario
    if not isinstance(selected,list) or len(selected)>32 or len(set(selected))!=len(selected) or any(p not in {r['id'] for r in scenario['rules']} for p in selected):raise ValueError('Invalid cited rules.')
    return {**scenario,'rules':[r for r in scenario['rules'] if r['id'] in selected]}

def supports(roots, conclusions, scenario):
    closure={(p['id'],p['positive']) for p in roots}
    terms={' '.join(n['hol'].split()):p for p,n in scenario['nodes'].items()}
    for _ in scenario['nodes']:
        before=len(closure)
        for rule in scenario['rules']:
            if all((p,True) in closure for p in rule['premises']):closure.add((rule['conclusion'],True))
        for term,p in terms.items():
            if term.startswith(r'\<not> ') and term[7:] in terms:
                q=terms[term[7:]]
                if (p,True) in closure:closure.add((q,False))
                if (q,True) in closure:closure.add((p,False))
        if len(closure)==before:break
    return all((p['id'],p['positive']) in closure for p in conclusions) and not any((p,not positive) in closure for p,positive in closure)

def mode(raw):
    value = raw.get('mode', 'assertion')
    if value not in ('assertion', 'conditional', 'backward'):
        raise ValueError('Unknown reasoning mode.')
    if 'mode' in raw:return value
    # Conservative protection for existing stored/schema-v1 conditional inputs.
    text = raw.get('text', '')
    if re.match(r'\s*(?:if\b|suppos(?:e|ing)\b|assuming\b)', text, re.I) or re.search(r'\b(?:if|then|provided that)\b', text, re.I):
        value = 'conditional'
    if re.search(r'\b(?:work(?:ing)? backwards?|subgoal|would need|need to establish)\b', text, re.I):
        value = 'backward'
    return value

def context(claim, accepted, scenario):
    """Restrict proof roots to stated premises/cited established steps.

    Given observations can be restated directly. Derived bare answers cannot
    acquire the scenario's entire proof as an unstated justification.
    """
    known = {(p, True) for p, n in scenario['nodes'].items() if n.get('fact')}
    by_id = {}
    for earlier in accepted:
        premises = earlier.get('assumptions', [])
        roots=list(premises)
        for dep in earlier.get('depends_on',[]):
            if by_id.get(dep):roots.extend(next(p['conclusions'] for p in accepted if p['id']==dep))
        if not roots:roots.extend(p for p in earlier['conclusions'] if scenario['nodes'][p['id']].get('fact') and p['positive'])
        earlier_scope=rule_scope(earlier,scenario)
        grounded = not earlier_scope.get('_invalid_citations') and mode(earlier) == 'assertion' and bool(roots) and all((p['id'], p['positive']) in known for p in premises) and supports(roots,earlier['conclusions'],earlier_scope)
        by_id[earlier['id']] = grounded
        if grounded:
            known.update((p['id'], p['positive']) for p in earlier['conclusions'])
    roots = list(claim.get('assumptions', []))
    cited = []
    for dep in claim.get('depends_on', []):
        prior = next((p for p in accepted if p['id']==dep), None)
        if prior and by_id.get(dep):
            cited.extend(prior['conclusions'])
    roots.extend(cited)
    answer_only=scenario.get('learning_task',{}).get('answer_only',False)
    if answer_only:roots.extend(dict(id=p,positive=True) for p,n in scenario['nodes'].items() if n.get('fact'))
    if not roots:
        roots.extend(p for p in claim['conclusions'] if (p['id'], p['positive']) in known and scenario['nodes'][p['id']].get('fact'))
    unique = list({(p['id'], p['positive']): p for p in roots}.values())
    values={(p['id'],p['positive']) for p in unique}
    if any((p,not positive) in values for p,positive in values):
        raise ValueError('Contradictory premises cannot establish a conclusion.')
    if unique and not supports(unique,unique,scenario):
        raise ValueError('These premises conflict under the supplied rules. A contradictory context cannot establish a conclusion.')
    stated = claim.get('assumptions', [])
    selected_scope=rule_scope(claim,scenario)
    grounded = not selected_scope.get('_invalid_citations') and mode(claim) == 'assertion' and bool(unique) and all((p['id'], p['positive']) in known for p in stated) and supports(unique,claim['conclusions'],selected_scope)
    # A bare restatement of a previously established derived result must cite it.
    unresolved = [p for p in stated if (p['id'], p['positive']) not in known]
    scoped = copy.deepcopy(selected_scope)
    for p, node in scoped['nodes'].items():
        node['fact'] = any(x['id'] == p and x['positive'] for x in unique)
    scoped['_negative_roots'] = [p['id'] for p in unique if not p['positive']]
    scoped['_learner_scope'] = True
    scoped['custom'] = True
    return dict(scenario=scoped, roots=unique, grounded=grounded,
                unresolved=unresolved, mode=mode(claim),
                state='answer_checked' if answer_only and grounded else 'established' if grounded else 'conditional' if mode(claim) != 'assertion' else 'unresolved')

def verification_scopes(claim,accepted,scenario):
    explicit=context(claim,accepted,scenario)
    established=[]
    for i,prior in enumerate(accepted):
        if context(prior,accepted[:i],scenario)['grounded']:established.extend(prior['conclusions'])
    givens=[dict(id=p,positive=True) for p,n in scenario['nodes'].items() if n.get('fact')]
    def scoped(roots):
        s=copy.deepcopy(scenario);unique=list({(p['id'],p['positive']):p for p in roots}.values())
        for p,n in s['nodes'].items():n['fact']=dict(id=p,positive=True) in unique
        s.update(_negative_roots=[p['id'] for p in unique if not p['positive']],_learner_scope=True,custom=True)
        return s
    hypothetical=claim['assumptions'] if mode(claim)!='assertion' else []
    scopes=[dict(id='scenario',label='Entire scenario',scenario=scoped(givens+hypothetical),claim=claim,inferred_dependencies=[],hypothetical=bool(hypothetical)),
            dict(id='learner',label='Established learner graph and recognised dependencies',scenario=scoped(givens+established+hypothetical),claim=claim,inferred_dependencies=[p['id'] for p in accepted if p['conclusions'] and all(lit in established for lit in p['conclusions'])],hypothetical=bool(hypothetical)),
            dict(id='explicit',label='My explicitly stated support',scenario=explicit['scenario'],claim=claim,inferred_dependencies=[],hypothetical=not explicit['grounded'])]
    learned={(p['id'],p['positive']) for p in established}
    targets=scenario['targets'];missing=[p for p in targets if (p,True) not in learned]
    goal=dict(id='coverage',text='Completion scope',conclusions=[dict(id=p,positive=True) for p in targets],assumptions=[],depends_on=[])
    # This scope contains only established learner conclusions: scenario facts
    # cannot fill an unvisited goal. No additional inference rules are permitted.
    completion=scoped(established);completion['rules']=[]
    scopes.append(dict(id='completion',label='Grounded goal coverage',scenario=completion,claim=goal,missing=missing,inferred_dependencies=[],hypothetical=False))
    for scope in scopes:
        roots=[dict(id=p,positive=True) for p,n in scope['scenario']['nodes'].items() if n.get('fact')]+[dict(id=p,positive=False) for p in scope['scenario'].get('_negative_roots',[])]
        scope['inconsistent']=not supports(roots,roots,scope['scenario'])
    return scopes

scenario_projection.py:
"""Reviewed finite projections of problem definitions, never attempted proofs.

Rules instantiate definitions over named entities. Only locale assumptions and
explicit ground definitions are facts. Browser certificates remain conditional
on this inspected finite projection; native Isabelle unfolds the problem itself.
"""
import re
import hashlib

DEFINITION_DIGESTS = {'murder-basic': 'c1e5f663fba9b9b6ec1f18576079d3d079a5b910c3e609b00183498c566fce21', 'murder-temporal': '38d8aa0b319cf0ca452f5bb92a3b7a9b781eafb01a153b480b72cb66da693f9e', 'murder-fuzzy': 'daa965a542862be1aedef56171bb2ff023af6de4947c9f442f5893b751806650', 'legal': 'd04c2476808634a97f0ff7cace189ee491b5a78adcc424df25d8d3f198d60f6c', 'sqrt-two': 'fa106e3c39977c44337e4c955ff1b31b58df633bfa29d13ffaa2ab7db8ce219d'}


def definition_digest(source):
    definitions=re.findall(r'\bdefinition\s+(\w+).*?\bwhere\s*"([^"]+)"',source,re.S)
    return hashlib.sha256(repr([(name,' '.join(body.split())) for name,body in definitions]).encode()).hexdigest()


def project(sid,source,locale,labels):
    if definition_digest(source)!=DEFINITION_DIGESTS[sid]:
        raise ValueError('These problem definitions need a reviewed projection before play.')
    nodes={};rules=[];aliases={};terms={}
    def add(name,term,label=None,fact=False,origin=None):
        term=' '.join(term.split())
        if term in terms:
            aliases[name]=terms[term];return terms[term]
        key='p'+str(len(nodes)+1);terms[term]=key;aliases[name]=key
        nodes[key]=dict(id=key,name=name,hol=term,label=label or labels.get(name,name.replace('_',' ')),fact=fact,covers=[key],origin=origin or 'definition consequence')
        return key
    def rule(name,term,premises,definition,label=None):
        key=add(name,term,label)
        rules.append(dict(id='r'+str(len(rules)+1),premises=[aliases[p] for p in premises],conclusion=key,source=definition))
        return key
    def base(term):
        key=terms.get(' '.join(term.split()))
        if not key or not nodes[key]['fact']:raise ValueError('The reviewed adapter requires a stated assumption: '+term)
        return nodes[key]['name']
    if locale:
        header=source.split('locale '+locale,1)[1].split('begin',1)[0]
        for name,term in re.findall(r'(\w+)\s*:\s*"([^"]+)"',header):add(name,term,fact=True,origin='problem assumption')
    if sid=='murder-basic':
        for person in ['Alice','Brian','Clara']:
            low=person.lower()
            # A proposition belongs to the vocabulary without being asserted.
            add(low+'_is_culprit','culprit '+person,person+' satisfies the fictional culprit criteria')
            available=['fingerprints_on_weapon '+person,'dna_at_scene '+person,r'\<not> verified_alibi '+person]
            if all(t in terms for t in available):rule(low+'_is_culprit','culprit '+person,[base(t) for t in available],'culprit_def')
            if 'verified_alibi '+person in terms:rule(low+'_not_culprit',r'\<not> culprit '+person,[base('verified_alibi '+person)],'culprit_def',person+' does not satisfy the culprit criteria')
    elif sid=='legal':
        for name,term in [('skydrop_commercial','commercial_operator SkyDrop'),('skydrop_deliveries','conducts_deliveries SkyDrop'),('skydrop_no_permit',r'\<not> has_permit SkyDrop')]:
            add(name,term,fact=True,origin='explicit problem definition')
        rule('skydrop_fails_ordinance',r'\<not> meets_ordinance SkyDrop',['skydrop_commercial','skydrop_deliveries','skydrop_no_permit'],'meets_ordinance_def')
        rule('skydrop_violates_ordinance','violates_ordinance SkyDrop',['skydrop_fails_ordinance'],'violates_ordinance_def')
    elif sid=='sqrt-two':
        rule('both_even',r'\<forall>m n::nat. m*m = 2*(n*n) \<longrightarrow> has_factor_two m \<and> has_factor_two n',['first_number_has_factor_two','second_number_has_factor_two'],'conjunction introduction','The equation forces both numbers to have a factor of two')
        rule('not_simplified',r'\<forall>m n::nat. m*m = 2*(n*n) \<longrightarrow> \<not> simplified_fraction m n',['both_even'],'simplified_fraction_def','Numbers satisfying the equation cannot form a simplified fraction')
        rule('no_candidate',r'\<not> (\<exists>m n::nat. candidate_fraction m n)',['not_simplified'],'candidate_fraction_def, sqrt_two_equation_def')
    else:
        fuzzy=sid=='murder-fuzzy'
        people=[('morgan','Morgan_Reed'),('casey','Casey_Lowe'),('jordan','Jordan_Pike')]
        presence='scene_presence_during_window' if fuzzy else 'present_during_window'
        scene=base('accepted_location Morgan_Reed T2110 Office_Corridor')
        rule('morgan_at_scene_2110','at_scene Morgan_Reed T2110',[scene],'at_scene_def','Morgan is at the scene at 21:10')
        rule('morgan_present_during_window',presence+' Morgan_Reed',['morgan_at_scene_2110'],'incident_window_def, '+presence+'_def','Morgan is present during the incident window')
        if not fuzzy:
            rule('morgan_temporally_capable','temporally_capable Morgan_Reed',['morgan_present_during_window',base(r'\<not> has_verified_alibi Morgan_Reed')],'temporally_capable_def','Morgan is temporally capable under the case rules')
        for low,person,place,exhibit in [('casey','Casey_Lowe','Number_47_Bus','Bus_CCTV'),('jordan','Jordan_Pike','Central_Hospital','Hospital_CCTV')]:
            supports=[];locations=[]
            usable='usable_alibi_support' if fuzzy else 'reliable_alibi_support'
            support='alibi_supports' if fuzzy else 'alibi_supports_presence'
            for time in ['T2110','T2115','T2120']:
                args=' '.join([exhibit,person,time,place]);name=low+'_support_'+time
                deps=[base(f'alibi_exhibit_{quality} {exhibit}') for quality in ['admissible','reliable','independent']]+[base(support+' '+args)]
                rule(name,usable+' '+args,deps,usable+'_def',low.capitalize()+' has reliable alibi support at '+time[1:3]+':'+time[3:]);supports.append(name)
                locations.append(base(' '.join(['accepted_location',person,time,place])))
            coverage='alibi_evidence_covers_window' if fuzzy else 'combined_evidence_covers_window'
            continuous='continuously_at_location' if fuzzy else 'continuously_at_location_during_window'
            rule(low+'_coverage',coverage+' '+person+' '+place,supports,'incident_window_def, '+coverage+'_def',low.capitalize()+"'s alibi evidence covers the complete incident window")
            rule(low+'_continuous',continuous+' '+person+' '+place,locations,'incident_window_def, '+continuous+'_def',low.capitalize()+' has accepted presence at the alibi location throughout the window')
            rule(low+'_verified_at','verified_alibi_at '+person+' '+place,[base('claims_alibi '+person+' '+place),low+'_coverage',low+'_continuous'],'verified_alibi_at_def',low.capitalize()+"'s stated alibi meets the verification conditions")
            rule(low+'_has_verified_alibi','has_verified_alibi '+person,[low+'_verified_at'],'has_verified_alibi_def',low.capitalize()+' has a verified alibi')
            if not fuzzy:rule(low+'_not_temporally_capable',r'\<not> temporally_capable '+person,[low+'_has_verified_alibi'],'temporally_capable_def',low.capitalize()+' is not temporally capable under the case rules')
        # Evidence integrity is separate from acceptance of offence elements.
        for exhibit in ['Corridor_CCTV','Knife_DNA','Bloodstained_Jacket']:
            required=[f'{q} {exhibit}' for q in ['continuity_preserved','method_validated','quality_controls_passed','examiner_competent','limitations_disclosed']]
            if all(t in terms for t in required):
                name=exhibit.lower()+'_integrity';rule(name,'forensic_integrity '+exhibit,[base(t) for t in required],'forensic_integrity_def')
                rule(exhibit.lower()+'_admissible','admissible '+exhibit,[name]+[base(t) for t in ['collected_lawfully '+exhibit,'relevant '+exhibit,r'\<not> excluded_by_court '+exhibit]],'admissible_def')
        for low,person in people:
            elements=('elements_proved '+person) if fuzzy else (low+'_elements_proved')
            add(low+'_elements',elements,low.capitalize()+"'s offence elements are established")
            sure=('legally_sure_of_guilt '+person) if fuzzy else ('sure_'+low+'_guilty')
            add(low+'_sure',sure,'The case rules establish legal sureness of '+low.capitalize()+"'s guilt")
            add(low+'_conviction_permitted','conviction_permitted '+person,'Conviction of '+low.capitalize()+' is permitted under the case rules')
            no_cause=r'\<not> fact_finder_accepts '+low.capitalize()+'_Caused_Fatal_Injury'
            if no_cause in terms:
                rule(low+'_no_elements',r'\<not> '+elements,[base(no_cause)],'elements_proved_def' if fuzzy else low+'_elements_proved_def',low.capitalize()+"'s offence elements are not established")
                rule(low+'_not_sure',r'\<not> '+sure,[low+'_no_elements'],'legally_sure_of_guilt_def' if fuzzy else 'sure_'+low+'_guilty_def')
                rule(low+'_conviction_not_permitted',r'\<not> conviction_permitted '+person,[low+'_not_sure'],'conviction_permitted_def')
                rule(low+'_acquittal_required','acquittal_required '+person,[low+'_conviction_not_permitted'],'acquittal_required_def','Acquittal of '+low.capitalize()+' is required under the case rules')
            else:
                findings=[base('fact_finder_accepts '+low.capitalize()+'_'+suffix) for suffix in ['Caused_Fatal_Injury','Intended_Death_Or_Serious_Injury','Acted_Unlawfully']]
                rule(low+'_elements',elements,findings,low+'_elements_proved_def')
        if not fuzzy:
            excluded=[base(r'\<not> realistic_possibility '+alt) for alt in ['Earlier_Innocent_Handling','Secondary_DNA_Transfer','Laboratory_Contamination','CCTV_Misidentification','Device_Not_Carried_By_Owner','Alibi_Record_Error','Unknown_Third_Party_Responsible']]
            rule('alternatives_excluded','relevant_alternatives_excluded',excluded,'relevant_alternatives_excluded_def','All relevant alternatives are excluded under the case rules')
            rule('morgan_sure','sure_morgan_guilty',['morgan_elements','morgan_temporally_capable','alternatives_excluded'],'sure_morgan_guilty_def')
            rule('morgan_conviction_permitted','conviction_permitted Morgan_Reed',['morgan_sure'],'conviction_permitted_def')
        else:
            scores={}
            for low,person in people:
                values=[];premises=[]
                for component in ['forensic','temporal','motive','conduct','alternative','alibi']:
                    found=[(term,key) for term,key in terms.items() if re.fullmatch(component+'_degree '+person+r' = \d+',term)]
                    if len(found)!=1:raise ValueError('Missing explicit component value')
                    term,key=found[0];values.append(int(term.split('=')[1]));premises.append(nodes[key]['name'])
                if not all(0<=v<=100 for v in values):raise ValueError('Degrees must be 0–100')
                f,t,m,c,a,b=values;score=4*f+4*t+m+c+2*(100-a)+3*(100-b);scores[low]=score
                rule(low+'_score',f'investigative_score {person} = {score}',premises,'investigative_score_def, residual_alternative_degree_def, residual_alibi_degree_def',low.capitalize()+f"'s investigative score equals {score}")
            for low,person in people:
                name=low+'_is_most_likely_suspect';term='most_likely_suspect '+person
                add(name,term,low.capitalize()+' is the highest-ranked (most likely) suspect by the comparative score')
                if scores[low]==max(scores.values()):rule(name,term,[p+'_score' for p,_ in people],'most_likely_suspect_def')
                else:rule(low+'_not_most_likely',r'\<not> '+term,[p+'_score' for p,_ in people],'most_likely_suspect_def')
            aliases['morgan_acquittal']=aliases['morgan_acquittal_required']
    return nodes,rules,aliases

challenge_generator.py:
"""Versioned, local procedural evidence reviews. No model-generated premises.

Subject vocabulary and presentation context are independent of the seeded
logical structure. Generated THY contains the problem and rules, never proofs.
"""
import hashlib
import json
import re

VERSION = 'evidence-review-v1'
SUBJECTS = {
    'humanities': dict(label='Humanities · sources and interpretation', record='catalogue entry', original='dated source transcription', check='separately held source copy', scope='the same passage, edition and period', explanation='edition change', method='Compare provenance, editions and the independence of accounts.'),
    'social': dict(label='Social sciences · methods and populations', record='survey summary', original='anonymised survey extract', check='separately collected survey sample', scope='the same question, population and time window', explanation='declared weighting adjustment', method='Distinguish the population studied, sampling decisions and independent evidence.'),
    'computing': dict(label='Computing and mathematics · models and evaluation', record='benchmark result', original='versioned benchmark log', check='separate held-out evaluation run', scope='the same task, metric and evaluation population', explanation='documented metric conversion', method='Check evaluation conditions, shared data and the limits of generalisation.'),
    'engineering': dict(label='Engineering · measurement and design', record='prototype report', original='calibrated measurement log', check='separate instrument run', scope='the same operating range and measurement units', explanation='documented unit conversion', method='Compare measurement provenance, operating conditions and reproducible checks.'),
    'science': dict(label='Natural sciences · experiments and reproducibility', record='experiment summary', original='versioned observation sheet', check='independent replication record', scope='the same procedure, conditions and measured quantity', explanation='documented baseline correction', method='Separate observations, transformations, replication and claims beyond the experiment.'),
    'business': dict(label='Business and policy · decisions and assumptions', record='service comparison', original='dated cost and usage worksheet', check='independent service audit', scope='the same service, accounting period and cost definition', explanation='documented accounting adjustment', method='Expose decision assumptions, comparison boundaries and the evidence needed to act.'),
    'researcher': dict(label='Researcher skills · integrity and open research', record='research output', original='versioned research record', check='independently preserved audit copy', scope='the same dataset, version and reported claim', explanation='documented analysis correction', method='Trace provenance, compare independent records, consider honest explanations and communicate uncertainty.')
}
CONTEXTS = {
    'criminal': dict(label='Criminal investigation', setting='a fictional non-graphic missing-property investigation', preview='Allegations, disputed testimony and a missing object. No death, graphic violence or real people. An allegation does not establish guilt.', concern='A witness alleges a discrepancy in', review='A further independent case-record investigation is warranted for', close='The documented explanation resolves the case-record discrepancy in', wait='The allegation needs further evidence for', theme='criminal'),
    'exhibition': dict(label='Campus exhibition', setting='a fictional university exhibition', preview='Catalogue discrepancies and display decisions. No death, crime or allegations against people.', concern='A display note reports a discrepancy in', review='A further accuracy review is warranted for', close='The documented explanation resolves the display discrepancy in', wait='The display decision needs further evidence for', theme='exhibition'),
    'garden': dict(label='Community garden', setting='a fictional community garden project', preview='Project records and planning choices. No personal accusations or violent content.', concern='A project note reports a discrepancy in', review='A further project-record review is warranted for', close='The documented explanation resolves the project discrepancy in', wait='The planning decision needs further evidence for', theme='garden'),
    'orbital': dict(label='Orbital archive', setting='a fictional orbital archive', preview='Fictional archive records and maintenance choices. No peril, death or personal accusations.', concern='An archive note reports a discrepancy in', review='A further archive-record review is warranted for', close='The documented explanation resolves the archive discrepancy in', wait='The archive decision needs further evidence for', theme='orbital'),
    'misconduct': dict(label='Research misconduct review', setting='a fictional research-integrity review', preview='Allegations of research-record manipulation, professional scrutiny and uncertainty. No real people or institutions; no graphic or violent material.', concern='A concern alleges possible manipulation of', review='Referral for further independent investigation is warranted for', close='The documented explanation resolves the reported discrepancy in', wait='The allegation cannot yet be decided; further evidence is needed for', theme='misconduct')
}
DIFFICULTIES = {
    'guided': 'Supported challenge',
    'challenge': 'Challenge',
    'stretch': 'Stretch challenge'
}

def options():
    return dict(version=VERSION, subjects=SUBJECTS, contexts=CONTEXTS, difficulties=DIFFICULTIES)

def configuration(value):
    if not isinstance(value, dict) or set(value)-{'version','subject','context','difficulty','seed'}:
        raise ValueError('Choose a subject, context, difficulty and seed.')
    c=dict(version=value.get('version',VERSION), subject=value.get('subject','researcher'), context=value.get('context','exhibition'), difficulty=value.get('difficulty','challenge'), seed=value.get('seed',''))
    if c['version'] != VERSION: raise ValueError('This generator version is unavailable; retain the original exported THY.')
    if c['subject'] not in SUBJECTS or c['context'] not in CONTEXTS or c['difficulty'] not in DIFFICULTIES:
        raise ValueError('Choose one of the available challenge settings.')
    if not isinstance(c['seed'],str) or not re.fullmatch(r'[A-Za-z0-9_-]{1,48}',c['seed']):
        raise ValueError('Use a seed of 1–48 letters, numbers, hyphens or underscores.')
    return c

class Random:
    def __init__(self,seed): self.state=int.from_bytes(hashlib.sha256(seed.encode()).digest()[:4],'big') or 1
    def choose(self,items):
        x=self.state;x^=(x<<13)&0xffffffff;x^=x>>17;x^=(x<<5)&0xffffffff;self.state=x&0xffffffff
        return items[self.state%len(items)]
    def shuffled(self,items):
        pool=list(items);out=[]
        while pool:
            item=self.choose(pool);pool.remove(item);out.append(item)
        return out

def generate(value):
    c=configuration(value);sub=SUBJECTS[c['subject']];ctx=CONTEXTS[c['context']]
    # Context and subject never silently change the evidence pattern. This also
    # permits deliberate transfer across skins with the same seed and level.
    rng=Random(VERSION+'|'+c['seed']+'|'+c['difficulty'])
    names=rng.shuffled(['Cedar','Lumen','Aster','Vale','Mosaic','Harbour'])[:2]
    profiles=['unresolved','explained'] if c['difficulty']=='guided' else ['unresolved','explained','shared','scope']
    nodes={};facts=[];rules=[];dossiers=[];requirements=[]
    def node(p,label,fact=False):
        nodes[p]=label
        if fact:facts.append(p)
        return p
    def rule(premises,conclusion):rules.append((premises,conclusion))
    for i,name in enumerate(names):
        p='d'+str(i+1)+'_';profile=rng.choose(profiles)
        labels={
            'trace':f'The {sub["original"]} for {name} has an identified source and version',
            'comparison':f'The source and reported {sub["record"]} for {name} have been compared item by item',
            'explained':f'A recorded {sub["explanation"]} exactly accounts for the discrepancy in {name}',
            'unresolved':f'The recorded comparison leaves a discrepancy unexplained in {name}',
            'independent':f'The cross-check of {name} uses {"an" if sub["check"][0].lower() in "aeiou" else "a"} {sub["check"]} with a separate evidence origin',
            'shared':f'The cross-check of {name} reproduces the same underlying evidence origin',
            'fits':f'The cross-check of {name} concerns {sub["scope"]}',
            'scope_gap':f'The cross-check of {name} concerns a different comparison scope from the reported claim',
            'usable':f'The discrepancy in {name} has a traceable comparison record',
            'qualified':f'The cross-check of {name} is both independent and applicable',
            'explanation':f'The documented transformation explains the discrepancy in {name}',
            'gap':f'The cross-check of {name} cannot settle this review',
            'review':f'{ctx["review"]} {name}',
            'close':f'{ctx["close"]} {name}',
            'wait':f'{ctx["wait"]} {name}'
        }
        givens={'trace','comparison', 'explained' if profile=='explained' else 'unresolved', 'shared' if profile=='shared' else 'independent', 'scope_gap' if profile=='scope' else 'fits'}
        for key,label in labels.items():node(p+key,label,key in givens)
        for before,after in [(['trace','comparison'],'usable'),(['usable','independent','fits'],'qualified'),(['usable','explained'],'explanation'),(['usable','shared'],'gap'),(['usable','scope_gap'],'gap'),(['qualified','unresolved'],'review'),(['qualified','explanation'],'close'),(['gap'],'wait')]:
            rule([p+b for b in before],p+after)
        # Observations are presented in a seeded order, not sorted by their use
        # in a solution. The learner sees reports separately from given facts.
        observations=rng.shuffled([p+k for k in labels if k in givens])
        dossiers.append(dict(name=name,report=f'{ctx["concern"]} {name}, a {sub["record"]}. This report is the claim being reviewed, not a verified finding.',observations=observations,reason_options=[p+'qualified',p+'explanation',p+'gap'],decision_options=[p+'review',p+'close',p+'wait']))
        requirements.extend([
            dict(id=p+'reason',label=f'Record a relevant evidence condition or limitation for {name}',any_of=[p+'qualified',p+'explanation',p+'gap'],support_routes=[dict(decision=p+'review',premises=[p+'independent',p+'fits'],warrant=p+'qualified'),dict(decision=p+'close',premises=[p+'explained'],warrant=p+'explanation'),dict(decision=p+'wait',premises=[p+'shared'],warrant=p+'gap'),dict(decision=p+'wait',premises=[p+'scope_gap'],warrant=p+'gap')],cue=f'For {name}, which origin, scope or documented transformation affects the inference?'),
            dict(id=p+'decision',label=f'State what should happen next for {name}',any_of=[p+'review',p+'close',p+'wait'],cue=f'For {name}, do the conditions support review, a documented resolution, or waiting for more evidence?')])
    boundary='A discrepancy alone does not establish intent or misconduct' if c['context']=='misconduct' else 'A discrepancy alone does not establish a cause or a conclusion beyond the compared records'
    node('boundary_rule',f'The review brief states: {boundary[0].lower()+boundary[1:]}',True)
    node('limits',boundary)
    rule(['boundary_rule','d1_usable','d2_usable'],'limits')
    node('recommendation','A report recording both justified dispositions and their limits is warranted')
    for a in ['review','close','wait']:
        for b in ['review','close','wait']:rule(['d1_'+a,'d2_'+b,'limits'],'recommendation')
    requirements.extend([dict(id='limits',label='State the boundary of the conclusion',any_of=['limits'],cue='What does the brief say a discrepancy cannot establish by itself?'),dict(id='recommendation',label='Combine both dispositions into a bounded recommendation',any_of=['recommendation'],cue='Have I justified each record separately and stated the limit of the combined report?')])
    if c['difficulty']!='guided':
        for i,name in enumerate(names):node('attention_'+str(i),f'The report about {name} has been repeated in {rng.choose([6,12,24,48])} summaries; these counts do not identify separate evidence origins',True)
    hypothetical=None
    if c['difficulty']=='stretch':
        name=rng.choose(names)
        hypothetical=f'In a separate hypothetical review of {name}, the only cross-check is now known to copy the original evidence and no independent replacement is supplied'
        node('changed_case',hypothetical,True)
        node('changed_decision',f'The hypothetical review of {name} needs an independent check before a disposition can be justified')
        node('changed_boundary','The hypothetical disposition does not replace the conclusions about the original records')
        rule(['changed_case'],'changed_decision');rule(['changed_case','boundary_rule'],'changed_boundary')
        requirements.extend([dict(id='changed_decision',label='Re-evaluate the changed evidence condition',any_of=['changed_decision'],cue='In the explicitly hypothetical review, which condition for a qualified check is unavailable?'),dict(id='changed_boundary',label='Keep the hypothetical and original cases distinct',any_of=['changed_boundary'],cue='Does changing the hypothetical record change the original observations?')])
    title='The Evidence Review · '+ctx['label']
    description=f'I am reviewing two disputed {sub["record"]}s in {ctx["setting"]}. I must compare evidence origins, check applicability, consider documented explanations, and justify what should happen next. {sub["method"]} All evidence and review rules are fictional and supplied in the brief.'
    metadata=json.dumps(c,sort_keys=True,separators=(',',':'))
    clauses=[f'f{i}: "{p}"' for i,p in enumerate(facts)]+[f'r{i}: "'+ ' & '.join(before)+' ==> '+after+'"' for i,(before,after) in enumerate(rules)]
    source=f'theory Evidence_Review imports Main begin\n(* thread:challenge {metadata} *)\n(* thread:title {title} *)\n(* thread:description {description} *)\n(* thread:goal recommendation,limits *)\n'
    source+='\n'.join(f'(* thread:label {p} = {label} *)' for p,label in nodes.items())
    source+='\nlocale Evidence_Review_Case = fixes '+' '.join(nodes)+' :: "bool"\nassumes '+'\n  and '.join(clauses)+'\nbegin end end\n'
    # Construction invariants guard runtime generation, not learner reasoning.
    reachable=set(facts)
    for _ in nodes:
        prior=len(reachable)
        for before,after in rules:
            if set(before)<=reachable:reachable.add(after)
        if len(reachable)==prior:break
    if len(nodes)>40 or any(not set(r['any_of'])&reachable for r in requirements):raise ValueError('Could not construct a complete challenge.')
    for dossier in dossiers:
        if len(set(dossier['decision_options'])&reachable)!=1:raise ValueError('The generated review has conflicting dispositions.')
    challenge=dict(config=c,subject_label=sub['label'],context_label=ctx['label'],theme=ctx['theme'],content_preview=ctx['preview'],method=sub['method'],dossiers=dossiers,requirements=requirements,hypothetical=hypothetical,concepts=['Source independence: repeated reports can share one evidence origin.','Scope and applicability: a sound method can still answer a different question.',('Alternative explanations: a discrepancy need not be deliberate misconduct.' if c['context']=='misconduct' else 'Alternative explanations: a discrepancy can have a documented explanation.'),'Calibrated decisions: further review, documented resolution and insufficient evidence are different outcomes.','Transfer: preserve the warrant when the setting changes, and re-evaluate it when the evidence changes.'])
    return dict(source=source,challenge=challenge,difficulty=DIFFICULTIES[c['difficulty']],goal='Justify a warrant and a disposition for each record, state what the evidence cannot establish, and combine these into a bounded recommendation.'+(' Then analyse the separate changed-evidence case.' if hypothetical else ''),hints=['Which facts establish an independent, applicable check rather than another copy of one source?','What documented explanation might account for the discrepancy?','What further evidence would distinguish the remaining possibilities?'],debrief='Which evidential conditions mattered across both records? Compare another subject or context using this seed, then a fresh seed. Explain what transfers and what must be checked again.')

def metadata_from_source(text):
    matches=re.findall(r'\(\*\s*thread:challenge\s+(.+?)\s*\*\)',text)
    if not matches:return {}
    if len(matches)!=1:raise ValueError('Use one challenge configuration.')
    try:generated=generate(json.loads(matches[0]))
    except (TypeError,ValueError) as e:raise ValueError('Invalid generated challenge configuration: '+str(e)) from e
    if generated['source'].strip()!=text.strip():
        raise ValueError('This generated challenge was edited. Regenerate it from its seed, or remove the thread:challenge comment to import it as an ordinary custom theory without the challenge completion requirements.')
    return {k:v for k,v in generated.items() if k!='source'}

journey_generator.py:
"""Bounded, replayable evidence acquisition. Stage facts never come from the LLM."""
import json
import re
from challenge_generator import configuration, SUBJECTS, CONTEXTS, Random

VERSION = 'evidence-journey-v1'
CHOICES = {
    'origin': {'label':'Trace the evidence origin', 'cost':1, 'purpose':'Find whether the existing check is independent or copied. This does not establish its scope.'},
    'scope': {'label':'Check applicability', 'cost':1, 'purpose':'Find whether the existing comparison addresses the same claim. This does not establish independence.'},
    'explanation': {'label':'Audit the proposed explanation', 'cost':1, 'purpose':'Find whether a documented transformation accounts for the discrepancy. An explanation alone does not qualify the cross-check.'},
    'independent': {'label':'Commission an independent comparison', 'cost':2, 'purpose':'Obtain a separately sourced comparison for the same scope. This does not establish why the discrepancy occurred.'},
    'defer': {'label':'Preserve the remaining budget', 'cost':0, 'purpose':'Obtain no new evidence. A limited conclusion can still be justified; unused budget is not a score.'},
}

def validated(value):
    if not isinstance(value,dict) or set(value)-{'version','config','choices'}:
        raise ValueError('Use a version, scenario configuration and a choice path.')
    if value.get('version',VERSION)!=VERSION: raise ValueError('This staged-review version is unavailable.')
    config=configuration(value.get('config',{})); choices=value.get('choices',[])
    if not isinstance(choices,list) or len(choices)>2 or any(not isinstance(c,str) or c not in CHOICES for c in choices):
        raise ValueError('Choose at most two listed evidence actions.')
    if sum(CHOICES[c]['cost'] for c in choices)>3: raise ValueError('This path exceeds the three-credit budget.')
    if len([c for c in choices if c!='defer'])!=len(set(c for c in choices if c!='defer')):
        raise ValueError('A completed evidence action cannot be purchased again.')
    return {'version':VERSION,'config':config,'choices':choices}

def source_for(title,description,labels,facts,rules,targets,marker):
    clauses=[f'f{i}: "{p}"' for i,p in enumerate(facts)]+[f'r{i}: "'+ ' & '.join(before)+' ==> '+after+'"' for i,(before,after) in enumerate(rules)]
    return ('theory Thread_Stage imports Main begin\n'+marker+'\n'
        +f'(* thread:title {title} *)\n(* thread:description {description} *)\n(* thread:goal '+','.join(targets)+' *)\n'
        +'\n'.join(f'(* thread:label {p} = {label} *)' for p,label in labels.items())
        +'\nlocale Thread_Stage_Case = fixes '+' '.join(labels)+' :: "bool"\nassumes '+'\n  and '.join(clauses)+'\nbegin end end\n')

def tutorial():
    labels={'pass':'My archive pass is valid','booked':'My archive visit is booked','open':'The archive is open',
            'ready':'My archive visit is ready','enter':'I may enter the archive'}
    title='Tutorial · The archive visit'
    description='I am visiting a fictional archive. I will practise stating a thought, reviewing its interpretation, checking it, and explaining the connection. No prior logic vocabulary is needed.'
    source=source_for(title,description,labels,['pass','booked','open'],[(['pass','booked'],'ready'),(['ready','open'],'enter')],['ready','enter'],'(* thread:lesson archive-v1 *)')
    return {'source':source,'tutorial':{'version':'archive-v1','steps':['ready','enter']},'difficulty':'Tutorial · guided practice',
            'goal':'Determine whether I may enter the archive by connecting the given facts and rules. The answer is not yet established in my reasoning.',
            'hints':['Which two given conditions make my visit ready?','Once my visit is ready, which extra condition lets me enter?'],
            'debrief':'Which rule connects the facts to my conclusion? How did reviewing the interpretation protect my meaning?'}

def generate(value):
    spec=validated(value); c=spec['config']; path=spec['choices']; stage=len(path)+1
    sub=SUBJECTS[c['subject']]; ctx=CONTEXTS[c['context']]
    rng=Random(VERSION+'|'+c['seed']+'|'+c['difficulty'])
    name=rng.choose(['Cedar','Lumen','Aster','Vale','Mosaic','Harbour'])
    # The evidence world is fixed before the path is chosen. Choice reveals
    # different portions of that world; it never rewards a preferred conclusion.
    independent=rng.choose([True,False]); fits=rng.choose([True,False]); explained=rng.choose([True,False])
    labels={
      'trace':f'The source and version of the {sub["original"]} for {name} are recorded',
      'comparison':f'The source and reported {sub["record"]} for {name} were compared item by item',
      'independent':f'The current cross-check of {name} has a separate evidence origin',
      'shared':f'The existing cross-check of {name} copies its evidence origin',
      'fits':f'The current cross-check of {name} addresses {sub["scope"]}',
      'scope_gap':f'The existing cross-check of {name} addresses a different scope',
      'explained':f'A recorded {sub["explanation"]} exactly accounts for the discrepancy in {name}',
      'unresolved':f'The completed explanation audit leaves the discrepancy in {name} unexplained',
      'coverage_gap':'At this stage, the collected checks do not establish all the conditions for a disposition',
      'usable':f'The discrepancy in {name} has a traceable comparison record',
      'qualified':f'The current cross-check of {name} is independent and applicable',
      'gap':f'The evidence collected at this stage cannot settle the review of {name}',
      'review':f'{ctx["review"]} {name}',
      'close':f'{ctx["close"]} {name}',
      'wait':f'{ctx["wait"]} {name}',
      'boundary':('The brief states that a discrepancy alone cannot establish intent or misconduct' if c['context']=='misconduct' else 'The brief states that a discrepancy alone cannot establish a cause or claims beyond the compared record'),
      'limits':'My conclusion is limited to this record and the checks collected at this stage',
      'report':'My stage report records a justified next action and the limits of the evidence',
    }
    facts=['trace','comparison','boundary']
    if 'origin' in path:facts.append('independent' if independent else 'shared')
    if 'scope' in path:facts.append('fits' if fits else 'scope_gap')
    if 'independent' in path:facts+=['independent','fits']
    if 'explanation' in path:facts.append('explained' if explained else 'unresolved')
    facts=list(dict.fromkeys(facts))
    if not {'independent','fits'}<=set(facts) or not {'explained','unresolved'}&set(facts):facts.append('coverage_gap')
    rules=[(['trace','comparison'],'usable'),(['usable','independent','fits'],'qualified'),
           (['usable','coverage_gap'],'gap'),(['gap'],'wait'),(['qualified','explained'],'close'),
           (['qualified','unresolved'],'review'),(['usable','boundary'],'limits')]
    for d in ['wait','close','review']:rules.append(([d,'limits'],'report'))
    if c['difficulty']!='guided':
        labels['repetition']=f'The report has been repeated in {rng.choose([6,12,24])} summaries that do not identify separate origins'
        labels['endorsement']='A fictional committee supports the report but supplies no additional observation'
        facts+=['repetition','endorsement']
    if c['difficulty']=='stretch':
        labels.update(changed='In a separate hypothetical case, the new comparison addresses a different population or version',changed_limit='The hypothetical comparison cannot settle the original claim',separate_case='The hypothetical result does not replace the observations collected in this stage')
        facts.append('changed');rules.extend([(['changed'],'changed_limit'),(['changed','boundary'],'separate_case')])
    # Single disposition is an invariant, including paths that collect too little.
    reachable=set(facts)
    for _ in labels:
        for before,after in rules:
            if set(before)<=reachable:reachable.add(after)
    if len(reachable&{'wait','close','review'})!=1:raise ValueError('Could not construct a consistent stage.')
    remaining=3-sum(CHOICES[p]['cost'] for p in path)
    available=[dict(id=k,**v,remaining=remaining-v['cost']) for k,v in CHOICES.items() if v['cost']<=remaining and (k=='defer' or k not in path)] if stage<3 else []
    title=f'The Evidence Review · Stage {stage} of 3'
    description=f'I review a disputed {sub["record"]}, {name}, in {ctx["setting"]}. I decide what the evidence currently supports, then choose which check to fund. Reports are allegations to examine. All observations and rules are fictional.'
    source=source_for(title,description,labels,facts,rules,['report','limits'], '(* thread:journey '+json.dumps(spec,sort_keys=True,separators=(',',':'))+' *)')
    requirements=[dict(id='basis',label='Record the traceable evidence basis',any_of=['usable'],cue='Which two observations make the comparison traceable?'),
                  dict(id='condition',label='Explain a qualifying condition or current evidence gap',any_of=['qualified','gap'],cue='Which conditions are established, and which checks have not yet been collected?'),
                  dict(id='decision',label='State the action justified at this stage',any_of=['review','close','wait'],cue='Does the supplied evidence support review, resolution, or waiting?'),
                  dict(id='limits',label='Keep the conclusion within its evidence',any_of=['limits'],cue='What does the current evidence leave undecided?'),
                  dict(id='report',label='Combine the action and limit',any_of=['report'],cue='Can I connect the action to the boundary of the conclusion?')]
    if c['difficulty']=='stretch':requirements.extend([dict(id='changed_limit',label='Limit the separate hypothetical inference',any_of=['changed_limit'],cue='What changes when the comparison concerns a different population or version?'),dict(id='separate_case',label='Keep the hypothetical separate',any_of=['separate_case'],cue='Does a hypothetical change replace an observation in my actual review?')])
    return dict(source=source,journey=dict(**spec,stage=stage,total=3,remaining=remaining,available=available,record=name,
        acquired=[dict(id=p,**CHOICES[p]) for p in path],stage_title=['Assess the starting evidence','Review the first new check','Make a bounded final recommendation'][stage-1]),
        challenge=dict(config=c,subject_label=sub['label'],context_label=ctx['label'],theme=ctx['theme'],content_preview=ctx['preview'],method=sub['method'],
         dossiers=[dict(name=name,report=f'{ctx["concern"]} {name}. This is a report to evaluate, not an established finding.',observations=facts,reason_options=['qualified','gap'],decision_options=['review','close','wait'])],
         requirements=requirements,hypothetical=None,concepts=['Evidence acquisition: choose a check that can distinguish possibilities, not just confirm my expectation.','Source independence and applicability are separate conditions.','Missing evidence is not proof of the opposite.','A justified decision is bounded by what has been collected.']),
        difficulty={'guided':'Supported','challenge':'Challenge','stretch':'Stretch'}[c['difficulty']]+' · three stages',
        goal='Establish the evidence basis, a qualifying condition or gap, a justified action, its limit, and a combined stage report.',
        hints=['Which conditions does the next inference actually need?','What could a new check reveal that would change my view?'],
        debrief='What did my chosen check add? Which alternative remains open? Was my choice useful even if it did not confirm my expectation?')

def metadata_from_source(text):
    markers=re.findall(r'\(\*\s*thread:(journey|lesson)\s+(.+?)\s*\*\)',text)
    if not markers:return {}
    if len(markers)!=1 or 'thread:challenge' in text:raise ValueError('Use one generated stage or tutorial marker.')
    kind,value=markers[0]
    if kind=='lesson':
        if value!='archive-v1':raise ValueError('Unknown tutorial version.')
        generated=tutorial()
    else:generated=generate(json.loads(value))
    if generated['source'].strip()!=text.strip():raise ValueError('This generated stage was edited. Regenerate it, or remove its generator marker to import an ordinary custom case.')
    return {k:v for k,v in generated.items() if k!='source'}

