"""Versioned method-specific evidence reviews; contextual text is not evidence."""
import copy, json, re
import learning_tasks_v2 as V2
import challenge_generator as G
from journey_generator import source_for
from generation_plan import transform
CATALOGUE=V2.CATALOGUE
MODES=V2.MODES
PRACTICES=V2.PRACTICES
VERSION='learning-tasks-v3'
EXTRA={'second_discipline','transformation_seed','content_range','mood','exposition'}

def config(value):
    if value.get('task_version')!=3:return V2.config(value)
    c=V2.config({**{k:v for k,v in value.items() if k not in EXTRA},'task_version':2})
    c['task_version']=3;c['second_discipline']=value.get('second_discipline','')
    if c['second_discipline'] and (c['second_discipline'] not in CATALOGUE['subjects'] or CATALOGUE['subjects'][c['second_discipline']]['area']!=c['second_subject']):raise ValueError('Choose a comparison discipline within the comparison pathway.')
    c['transformation_seed']=value.get('transformation_seed',c['seed'])
    if not isinstance(c['transformation_seed'],str) or not re.fullmatch(r'[A-Za-z0-9_-]{1,48}',c['transformation_seed']):raise ValueError('Use a bounded transformation seed.')
    c['content_range']=value.get('content_range','standard')
    if c['content_range'] not in ('standard','adult_professional'):raise ValueError('Choose a supported thematic range.')
    if c['content_range']=='adult_professional' and (c['context'] not in ('criminal','misconduct') or not c['sensitive']):raise ValueError('Adult professional themes require a sensitive setting and explicit consent.')
    for key,limit in [('mood',120),('exposition',420)]:c[key]=V2.plain(value.get(key,''),limit,key)
    return c

def add_transfer(c,result,labels,facts,rules,targets):
    task=result['learning_task'];practice=next(p for p in PRACTICES if p['id']==task['practice']);pid=practice['id'];method='task_method_'+pid
    example=task['example_case'];second=CATALOGUE['subjects'].get(c['second_discipline'],{}).get('label')
    if second:
        example['title']='A separate example in '+second
        example['description']=example['description'].replace('In ', 'In a fictional '+second.lower()+' review within ',1)
    example['subject']=c['second_subject'];example['discipline']=c['second_discipline']
    labels['task_example']=example['description'];rules[:]=[(a,b) for a,b in rules if b!='task_transfer']
    for p in PRACTICES:labels['task_method_'+p['id']]='The separate example uses '+p['name'].lower()
    rules.append((['task_example'],method))
    labels['task_transfer']='My recommendation transfers '+practice['name'].lower()+' to both new records using their actual observations'
    targets.append(method);result['challenge']['requirements'].append(dict(id='method',label='Identify the example’s method',any_of=[method],cue=practice['question']))
    apps=[]
    for index,dossier in enumerate(result['challenge']['dossiers'],1):
        p='d'+str(index)+'_';app='task_'+pid+'_d'+str(index);apps.append(app)
        origin=p+('independent' if p+'independent' in facts else 'shared');scope=p+('fits' if p+'fits' in facts else 'scope_gap');outcome=p+('explained' if p+'explained' in facts else 'unresolved')
        if pid=='independence':
            labels[app]='My review of '+dossier['name']+' distinguishes a separate evidence origin from copies, and checks whether the comparison addresses the same claim';before=[method,p+'usable',origin,scope]
        elif pid=='conditions':
            labels[app]='My review of '+dossier['name']+' checks independence and applicability together instead of treating either necessary condition as sufficient';before=[method,p+'usable',origin,scope]
        elif pid=='popularity':
            count='task_endorsement_'+str(index);labels[count]='The example’s endorsement count supplies no new observation about '+dossier['name'];facts.append(count)
            labels[app]='My review of '+dossier['name']+' separates endorsement count from independent applicable evidence';before=[method,count,origin,scope]
        else:
            labels[app]='My review of '+dossier['name']+' considers the recorded transformation as an alternative explanation and respects whether the discrepancy remains unexplained';before=[method,p+'usable',outcome]
        rules.append((before,app));targets.append(app);result['challenge']['requirements'].append(dict(id=app,label='Transfer the method to '+dossier['name'],any_of=[app],cue=practice['question']+' Use this record’s given observations.'))
    rules.append((['recommendation',method]+apps,'task_transfer'))
    task['transfer']={'method':method,'applications':apps,'completion':'task_transfer','practice':pid,'wrong_methods':['task_method_'+p['id'] for p in PRACTICES if p['id']!=pid]}

def vary_evaluation(c,result,labels):
    pairs=[
      ([['Traceability','Many endorsements'],'Independence and applicability','The stated reasons do not establish independence and matching scope'],[['Separate evidence origin','Matching comparison scope'],'An independent and applicable check','The conditional argument supplies both conditions required for a qualified check']),
      ([['Separate evidence origin','Matching comparison scope'],'An independent and applicable check','The conditional argument supplies both conditions required for a qualified check'],[['Many endorsements','A repeated summary'],'Accuracy has been established','Endorsement and repetition do not supply an independent applicable observation']),
      ([['Separate evidence origin','Matching comparison scope'],'An independent and applicable check','The conditional argument supplies both conditions required for a qualified check'],[['A qualified cross-check','A documented transformation explains the discrepancy'],'A documented resolution is warranted','The conditional argument supplies the qualified comparison and explanation required for resolution']),
      ([['Separate evidence origin'],'An independent and applicable check','A separate origin alone leaves matching scope unsupported'],[['The original record is traceable','The records were compared item by item'],'A traceable comparison record','The conditional argument justifies traceability of the comparison without claiming independence or a final disposition'])]
    variant=G.Random(c['seed']+'|argument-pair-v3').choose(list(range(len(pairs))))
    arguments=[]
    for key,spec in zip(('a','b'),pairs[variant]):
        roots,end,evaluation=spec;upper=key.upper();arguments.append(dict(id=upper,speaker='Reviewer '+upper,premises=roots,conclusion=end,status='proposed'))
        labels['task_arg_'+key]='Reviewer '+upper+' proposes '+end.lower()+' from '+', '.join(r.lower() for r in roots)
        labels['task_eval_'+key]='Reviewer '+upper+': '+evaluation[0].lower()+evaluation[1:]
    labels['task_arg_rule']='The supplied criteria require separate origin AND matching scope for a qualified check; traceability AND item-by-item comparison establish a usable record; resolution additionally requires an explanation. Endorsements do not supply these conditions.'
    result['learning_task'].update(arguments=arguments,argument_variant=variant)
    for obligation in result['challenge']['requirements']:
        if obligation['id'] in ('task_eval_a','task_eval_b'):obligation['label']=labels[obligation['id']]

def vary_debate(c,result,labels,facts,rules):
    task=result['learning_task'];stage=result['journey']['stage'];variants=[
      [('Endorsement settles the review','Endorsements do not add independent observations','origin','Where is the independent observation behind that endorsement?','scope','Even an independent account must address the same claim.'),('Traceability alone settles the cross-check','The review requires traceability, independent origin and matching scope together','origin','Tracing a report is not the same as obtaining independent evidence.','scope','Which observation establishes that this comparison addresses the same claim?')],
      [('A discrepancy establishes deliberate deception','A discrepancy alone cannot establish intent','intent','A discrepancy does not establish deliberate intent.','explanation','What documented transformation could explain the discrepancy?'),('A plausible explanation closes the case immediately','A plausible explanation must be documented and account for the discrepancy','documentation','Plausibility alone does not establish the explanation.','fit','Does the documented explanation actually account for this discrepancy?')],
      [('An earlier stage’s conclusion cannot change','Stage conclusions depend on the observations collected in that stage','revision','My previous conclusion depended on the previous evidence.','limits','How do the new observations change the limits of that conclusion?'),('Collecting more reports must settle the case','Additional reports must improve the required evidence conditions, rather than repeat the same origin','origin','More repetitions do not supply a separate origin.','limits','Which remaining condition is still unestablished after these checks?')]]
    v=G.Random(c['seed']+'|debate-v3|'+str(stage)).choose(variants[stage-1]);witness,criterion,a,reply_a,b,reply_b=v
    labels['debate_testimony']='The opposing reviewer asserts: '+witness;labels['debate_criterion']='The supplied debate criterion states: '+criterion
    exchanges=[]
    for key,reply in [(a,reply_a),(b,reply_b)]:
        node='debate_objection_'+key;labels[node]='My objection identifies this gap: '+reply
        rules.append((['debate_testimony','debate_criterion'],node));rules.append(([node],'debate_objection'))
        exchanges.append({'objection':node,'response':reply,'next_prompt':'Connect this specific gap to my stage report; what can I now claim and what remains uncertain?'})
    task['debate'].update(opponent=witness,criterion=criterion,exchanges=exchanges,variant='|'.join((a,b)),response_policy='Use the first grounded specific objection to choose an opponent response; unvisited alternatives stay unvisited.')

def generate(value,choices=()):
    if value.get('task_version')!=3:return V2.generate(value,choices)
    c=config(value);result=copy.deepcopy(V2.generate({**{k:v for k,v in c.items() if k not in EXTRA},'task_version':2},choices))
    labels,facts,rules,targets=V2.source_parts(result['source']);task=result['learning_task'];task.update(version=VERSION,config=c)
    if c['task'] in ('apply_reasoning','analysis'):add_transfer(c,result,labels,facts,rules,targets)
    if c['task']=='evaluate':vary_evaluation(c,result,labels)
    if c['task']=='debate':vary_debate(c,result,labels,facts,rules)
    labels,facts,rules,plan=transform(labels,facts,rules,targets,c,result['challenge']);task['generation']=plan
    description=result['description']
    if c['mood']:description+=' My chosen atmosphere is '+c['mood']+'.'
    if c['exposition']:description+=' My editable scene introduction: '+c['exposition']+' This introduction supplies no additional evidence.'
    if c['content_range']=='adult_professional':
        notice='Adult professional themes: possible disciplinary or legal scrutiny, financial consequences and reputational pressure. No graphic violence, sexual content or detailed descriptions of harm. Allegations remain unproved.'
        result['challenge']['content_preview']+=' '+notice;description+=' The fictional review includes adult professional stakes; evidence limits still apply.'
    task['narrative'].update(mood=c['mood'],exposition=c['exposition'],role='editable aesthetic context; no premise authority')
    marker='(* thread:task '+json.dumps(dict(config=c,choices=list(choices)),sort_keys=True,separators=(',',':'),ensure_ascii=True)+' *)'
    result['source']=source_for(result.get('title','The Evidence Review'),description,labels,list(dict.fromkeys(facts)),rules,list(dict.fromkeys(targets)),marker)
    result['description']=description;result['challenge']['config']=c
    if result.get('journey'):result['journey']['task_config']=c
    return result

def metadata_from_source(text):
    markers=re.findall(r'\(\*\s*thread:task\s+(.+?)\s*\*\)',text)
    if not markers:return {}
    if len(markers)!=1:raise ValueError('Use one learning task marker.')
    spec=json.loads(markers[0]);result=generate(spec['config'],spec['choices'])
    if result['source'].strip()!=text.strip():raise ValueError('This learning task was edited. Regenerate it or remove its marker before an ordinary custom import.')
    return {k:v for k,v in result.items() if k not in ('source','description')}

