"""Verified task formats over the seeded evidence graph, separate from themes.

These are bounded instructional templates, not arbitrary LLM authored problems.
"""
import json
import re
import challenge_generator as G
from pathlib import Path
CATALOGUE=json.loads(Path(__file__).with_name('subject-catalogue.json').read_text(encoding='utf-8'))

VERSION='learning-tasks-v1'
MODES={
 'identify_solution':dict(label='Identify a solution',instruction='Identify the bounded recommendation supported by the supplied evidence. In this introductory task an answer check is enough; it does not assess an explanation.',level=1),
 'identify_reasoning':dict(label='Identify a reasoning gap',instruction='Review the proposed argument below. Identify which required condition it leaves unsupported, then justify that gap from the supplied description and rule.',level=1),
 'explain_reasoning':dict(label='Explain reasoning',instruction='Explain why a proposed disposition is supported or unsupported. Connect the evidence conditions, the disposition and the limit; a proposal is not a given fact.',level=2),
 'apply_reasoning':dict(label='Apply a method',instruction='In a separate example, several copies of one source are not independent evidence. Apply the same source-independence and scope checks to these new records.',level=3),
 'analysis':dict(label='Analyse evidence',instruction='Analyse the relationship between the records and the competing recommendations. Decide which conditions matter and what the evidence leaves open.',level=4),
 'evaluate':dict(label='Evaluate arguments',instruction='Compare the arguments for both records. Distinguish independent support, applicability and explanations; justify a bounded recommendation rather than count endorsements.',level=5),
 'investigation':dict(label='Investigate with evidence choices',instruction='Justify a provisional disposition, choose which check to fund, and revise when new evidence arrives. A record discrepancy alone does not establish intent.',level=6),
 'debate':dict(label='Debate with evidence choices',instruction='Prepare a fair case, consider the strongest alternative and choose how to allocate checking time. This is solo argument practice; no peer communication is provided.',level=6),
}

def config(value):
    if not isinstance(value,dict) or set(value)-{'version','subject','context','difficulty','seed','task','interest','discipline'}:raise ValueError('Unknown learning-task option.')
    task=value.get('task','evaluate');interest=value.get('interest','')
    if task not in MODES:raise ValueError('Choose a listed task format.')
    if not isinstance(interest,str) or len(interest)>80 or (interest and not re.fullmatch(r"[A-Za-z0-9 ,.'-]+",interest)):raise ValueError('Use up to 80 letters, numbers and ordinary punctuation for an optional interest.')
    base=G.configuration({k:v for k,v in value.items() if k not in ('task','interest','discipline')})
    discipline=value.get('discipline','')
    if discipline and (discipline not in CATALOGUE['subjects'] or CATALOGUE['subjects'][discipline]['area']!=base['subject']):raise ValueError('Choose a discipline within the selected subject pathway.')
    return dict(**base,task=task,interest=interest,discipline=discipline)

def generate(value,choices=()):
    c=config(value);mode=MODES[c['task']]
    if mode['level']!=6 and choices:raise ValueError('Evidence choices belong to a staged task.')
    base={k:v for k,v in c.items() if k not in ('task','interest','discipline')}
    if mode['level']==6:
        import journey_generator as J
        result=J.generate(dict(config=base,choices=list(choices)));result['journey']['budget_unit']='hours' if c['task']=='debate' else 'credits';result['journey']['task_config']=c
    else:result=G.generate(base)
    source=result['source']
    # Replace the generator marker; import regenerates this exact source and
    # checks it for tampering before giving any task metadata authority.
    source=re.sub(r'\(\*\s*thread:(?:challenge|journey)\s+.+?\*\)', '(* thread:task '+json.dumps(dict(config=c,choices=list(choices)),sort_keys=True,separators=(',',':'))+' *)', source,count=1)
    task=dict(version=VERSION,mode=c['task'],label=mode['label'],instruction=mode['instruction'],complexity=mode['level'],config=c,answer_only=c['task']=='identify_solution')
    result['challenge']['subject_label']=CATALOGUE['subjects'][c['discipline']]['label'] if c['discipline'] else G.SUBJECTS[c['subject']]['label']
    requirements=result['challenge']['requirements']
    if c['task']=='identify_solution':
        source=re.sub(r'\(\* thread:goal [^\n]+\*\)','(* thread:goal recommendation *)',source)
        result['challenge']['requirements']=[dict(id='answer',label='Identify the bounded recommendation',any_of=['recommendation'],cue='Which recommendation follows from the displayed evidence?')]
    elif c['task']=='identify_reasoning':
        # Formalise an argument's explicitly displayed contents, not a guessed
        # student's error. Neither the proposal nor its conclusion is a fact.
        task['proposal']='The proposed argument lists traceability as its only reason for claiming that the cross-check is independent and applicable.'
        from journey_generator import source_for
        marker='(* thread:task '+json.dumps(dict(config=c,choices=[]),sort_keys=True,separators=(',',':'))+' *)'
        source=source_for('Reasoning gap · '+G.CONTEXTS[c['context']]['label'],'I review a short proposed argument in '+G.CONTEXTS[c['context']]['setting']+'. All descriptions and rules are fictional.',
          dict(task_stated='The proposed argument lists traceability as its only premise',task_required='The supplied rule requires traceability, independence and applicability together',task_gap='The proposed argument does not justify independence and applicability'),['task_stated','task_required'],[(['task_stated','task_required'],'task_gap')],['task_gap'],marker)
        result['challenge']['dossiers']=[];result['challenge']['hypothetical']=None
        result['challenge']['requirements']=[dict(id='gap',label='Justify the missing argument conditions',any_of=['task_gap'],cue='Which conditions does the proposal actually supply, and which does the rule require?')]
    elif c['task']=='explain_reasoning':
        task['proposal']='A reviewer proposes further review for both records. I must check each proposal rather than accept it as evidence.'
    suffix=(' The fictional visual setting takes inspiration from my chosen interest: '+c['interest']+'.') if c['interest'] else ''
    source=re.sub(r'\(\* thread:description (.+?) \*\)',lambda m:'(* thread:description '+m[1]+' '+mode['instruction']+suffix+' *)',source,count=1)
    result.update(source=source,learning_task=task,description=result.get('description','')+suffix,goal=mode['instruction'])
    result['challenge']['config']=c
    return result

