"""Seeded graph operations, independently reproducible from narrative data."""
import copy, hashlib, json
from challenge_generator import Random
VERSION='evidence-transform-v1'

def closure(facts,rules):
    known=set(facts)
    for _ in range(len(rules)+1):
        before=len(known)
        for roots,conclusion in rules:
            if set(roots)<=known:known.add(conclusion)
        if len(known)==before:break
    return known

def shape(labels,facts,rules):return {'nodes':list(labels),'facts':sorted(facts),'rules':[{'premises':list(a),'conclusion':b} for a,b in rules]}
def digest(data):return hashlib.sha256(json.dumps(data,sort_keys=True,separators=(',',':')).encode()).hexdigest()

def transform(labels,facts,rules,targets,c,challenge):
    labels=copy.deepcopy(labels);facts=list(facts);rules=copy.deepcopy(rules);original=shape(labels,facts,rules);known=closure(facts,rules)
    rng=Random(VERSION+'|'+c['transformation_seed']+'|'+c['task']+'|'+str(len(facts)));operations=[]
    inactive=[i for i,(a,b) in enumerate(rules) if not set(a)<=known and b not in targets]
    if inactive:
        index=rng.choose(inactive);a,b=rules.pop(index);operations.append({'kind':'delete_inactive_alternative','premises':a,'conclusion':b,'reason':'Premises are not all established in this generated case; deletion does not negate the conclusion.'})
    eligible=[i for i,(a,b) in enumerate(rules) if set(a)<=known and len(a)>1 and not b.startswith('task_')]
    if not eligible:eligible=[i for i,(a,b) in enumerate(rules) if set(a)<=known]
    if eligible:
        index=rng.choose(eligible);a,b=rules.pop(index);bridge='transform_bridge';labels[bridge]='The displayed conditions for '+labels[b][0].lower()+labels[b][1:]+' have been checked together'
        rules[index:index]=[(a,bridge),([bridge],b)];operations.append({'kind':'split_warrant','premises':a,'bridge':bridge,'conclusion':b,'reason':'Make one connecting warrant explicit; preserve the conclusion’s required conditions.'})
    candidates=[(a,b) for a,b in rules if len(a)>1 and not b.startswith('task_')];draft=[]
    if candidates:
        a,b=rng.choose(candidates);draft=[{'premises':[a[0]],'conclusion':b,'missing_conditions':a[1:],'status':'untrusted draft; excluded from formal rules and facts'}]
        operations.append({'kind':'propose_incomplete_branch','draft':draft[0],'reason':'Inspect a tempting shortcut that omits required conditions. It has no premise authority.'})
    reachable=closure(facts,rules)
    if not set(targets)<=reachable or any(not set(r['any_of'])&reachable for r in challenge['requirements']):raise ValueError('The transformed task lost a required reachable goal.')
    if len(labels)>64:raise ValueError('The transformed task exceeds the supported proposition bound.')
    current=shape(labels,facts,rules)
    plan={'version':VERSION,'structure_seed':c['seed'],'transformation_seed':c['transformation_seed'],'base_digest':digest(original),'transformed_digest':digest(current),'base_graph':original,'problem_graph':current,'operations':operations,'draft_branches':draft,'invariants':{'reachable_goals':True,'facts_unchanged':set(facts)==set(original['facts']),'drafts_excluded':True},'phases':{'structure':'constructed','transformation':'validated','context':'provided' if c['source_notes'] or c['source_url'] else 'skipped','narrative':'editable context applied','review':'ready'}}
    return labels,facts,rules,plan

logic/temporal.py:
"""LTL on a fully specified ultimately periodic trace, without server services.

The last stored state jumps to ``loop_start``. F and U are least fixed points;
G is a greatest fixed point. This is infinite-trace LTL, not bounded lookahead.
Results describe this trace only, not all runs of a transition system. The
Python evaluator is inspected evidence; the ordinary Horn certificate checks
the learner's dependencies over the scenario's reviewed trace projection.
"""
from __future__ import annotations
import copy
import hashlib
import json
import re


class TemporalError(ValueError):
    pass


def validate_model(model):
    if not isinstance(model, dict) or set(model) - {'states', 'loop_start', 'queries', 'labels'}:
        raise TemporalError('Use states, loop_start and named queries for a complete lasso trace.')
    states = model.get('states')
    if not isinstance(states, list) or not 1 <= len(states) <= 128:
        raise TemporalError('Use one to 128 stored states.')
    if any(not isinstance(s, dict) for s in states):
        raise TemporalError('Every state assigns each declared atom a Boolean value.')
    atoms = set(states[0])
    if not 1 <= len(atoms) <= 32 or any(not isinstance(a, str) or not re.fullmatch(r'[a-z][a-z0-9_]{0,63}', a) for a in atoms):
        raise TemporalError('Use one to 32 lower-case atom names.')
    if any(set(s) != atoms or any(type(v) is not bool for v in s.values()) for s in states):
        raise TemporalError('All states must assign exactly the same atoms; missing values are not false.')
    loop = model.get('loop_start')
    if type(loop) is not int or not 0 <= loop < len(states):
        raise TemporalError('The loop start must name a stored state.')
    return states, loop, atoms


def evaluate(model, formula, start=0):
    states, loop, atoms = validate_model(model)
    if type(start) is not int or not 0 <= start < len(states):
        raise TemporalError('Choose a stored start state.')
    n = len(states)
    successors = list(range(1, n)) + [loop]
    count = 0
    evaluations = {}

    def calc(expr, depth=0):
        nonlocal count
        count += 1
        if count > 256 or depth > 24:
            raise TemporalError('The formula is too large for this trace inspector.')
        if type(expr) is bool:
            values = [expr] * n
        elif isinstance(expr, str):
            if expr not in atoms:
                raise TemporalError('Every formula atom must be declared in the trace.')
            values = [s[expr] for s in states]
        elif isinstance(expr, dict) and set(expr) == {'op', 'args'}:
            op, args = expr['op'], expr['args']
            if op not in ('not', 'and', 'or', 'implies', 'X', 'F', 'G', 'U') or not isinstance(args, list):
                raise TemporalError('Supported operators: not, and, or, implies, X, F, G and strong U.')
            arity = 1 if op in ('not', 'X', 'F', 'G') else 2
            if len(args) != arity:
                raise TemporalError('An operator has the wrong number of arguments.')
            operands = [calc(a, depth + 1) for a in args]
            a = operands[0]
            if op == 'not': values = [not v for v in a]
            elif op == 'X': values = [a[successors[i]] for i in range(n)]
            elif op == 'and': values = [a[i] and operands[1][i] for i in range(n)]
            elif op == 'or': values = [a[i] or operands[1][i] for i in range(n)]
            elif op == 'implies': values = [not a[i] or operands[1][i] for i in range(n)]
            else:
                # Monotone fixed-point iteration terminates in at most n
                # state changes along a lasso for these unary recurrences.
                values = [op == 'G'] * n
                for _ in range(n + 1):
                    if op == 'F': updated = [a[i] or values[successors[i]] for i in range(n)]
                    elif op == 'G': updated = [a[i] and values[successors[i]] for i in range(n)]
                    else: updated = [operands[1][i] or (a[i] and values[successors[i]]) for i in range(n)]
                    if updated == values: break
                    values = updated
                else:
                    raise TemporalError('The fixed point did not converge within the trace bound.')
        else:
            raise TemporalError('Use a Boolean, atom name, or a structured operator expression.')
        evaluations[json.dumps(expr, sort_keys=True)] = values
        return values

    values = calc(formula)
    path, seen, cursor = [], set(), start
    while cursor not in seen:
        seen.add(cursor); path.append(cursor); cursor = successors[cursor]
    evidence = {'path': path, 'repeats_from': cursor, 'kind': 'valuation on all reachable stored states'}
    if isinstance(formula, dict):
        op, args = formula['op'], formula['args']
        a = evaluations[json.dumps(args[0], sort_keys=True)]
        if op == 'X': evidence.update(kind='next-state evaluation', witness_state=successors[start])
        elif op == 'F': evidence.update(kind='eventual witness' if values[start] else 'no witness in the reachable prefix or loop', witness_state=next((i for i in path if a[i]), None))
        elif op == 'G': evidence.update(kind='invariant' if values[start] else 'counterexample state', counterexample_state=next((i for i in path if not a[i]), None))
        elif op == 'U':
            b = evaluations[json.dumps(args[1], sort_keys=True)]
            witness = None; counterexample = None
            for i in path:
                if b[i]: witness = i; break
                if not a[i]: counterexample = i; break
            evidence.update(kind='strong-until witness' if values[start] else ('left condition fails before the right condition' if counterexample is not None else 'right condition never occurs in the loop'), witness_state=witness, counterexample_state=counterexample)
    return {'holds': values[start], 'start': start, 'values': values, 'evidence': evidence,
            'semantics': 'infinite ultimately periodic trace; the final stored state returns to loop_start',
            'scope': 'This specified trace only. This evaluator is not a Rocq or Isabelle theorem certificate.',
            'model_hash': hashlib.sha256(json.dumps(model, sort_keys=True, separators=(',', ':')).encode()).hexdigest()}


def inspect_scenario(scenario, query_id):
    model = scenario.get('temporal_model')
    if not isinstance(model, dict):
        raise TemporalError('This scenario has no reviewed temporal trace.')
    queries = model.get('queries', [])
    if not isinstance(queries, list) or len(queries) > 32:
        raise TemporalError('Use at most 32 named queries.')
    query = next((q for q in queries if isinstance(q, dict) and q.get('id') == query_id), None)
    if not query:
        raise TemporalError('Choose a query supplied by the scenario.')
    result = evaluate(model, query.get('formula'), query.get('start', 0))
    if type(query.get('expected')) is not bool or result['holds'] != query['expected']:
        raise TemporalError('The trace does not match its reviewed projection; this scenario needs review.')
    return dict(result, id=query_id, title=query.get('title', query_id), formula=copy.deepcopy(query['formula']))

