"""Bounded symbolic possible worlds for the supported Boolean/Horn adapter.

Modal queries are universal/existential over admissible valuations, not claims
about unrestricted HOL or arbitrary Kripke accessibility relations.
"""
import re
def clauses(s):
 ids={p:i+1 for i,p in enumerate(s['nodes'])};cnf=[[ids[p]] for p,n in s['nodes'].items() if n.get('fact')]+[[-ids[p]] for p in s.get('_negative_roots',[])]
 cnf += [[-ids[p] for p in r['premises']]+[ids[r['conclusion']]] for r in s['rules']]
 terms={re.sub(r'\s+',' ',n['hol']).strip():p for p,n in s['nodes'].items()}
 for t,p in terms.items():
  if t.startswith(r'\<not> ') and t[7:] in terms:cnf.append([-ids[p],-ids[terms[t[7:]]]])
 return ids,cnf
def satisfiable(cnf,limit=20000):
 work=[0]
 def solve(cs):
  work[0]+=1
  if work[0]>limit:raise ValueError('World query exceeded its bounded search budget.')
  while True:
   if any(not c for c in cs):return False
   if not cs:return True
   unit=next((c[0] for c in cs if len(c)==1),None)
   if unit is None:break
   cs=[[x for x in c if x!=-unit] for c in cs if unit not in c]
  atom=min(cs,key=len)[0]
  return solve(cs+[[atom]]) or solve(cs+[[-atom]])
 return solve(cnf)
def query(s,e,accepted=None,scope='scenario'):
 if scope not in ('scenario','learner'):raise ValueError('Choose scenario or learner world scope.')
 if scope=='learner':
  import copy
  values=state(s,accepted or [])['learner_values'];s=copy.deepcopy(s)
  for p,n in s['nodes'].items():n['fact']=any(v['id']==p and v['positive'] for v in values)
  s['_negative_roots']=[v['id'] for v in values if not v['positive']]
 ids,cnf=clauses(s);budget=[0];serial=[len(ids)];seen=set()
 def expr(x,depth=0):
  budget[0]+=1
  if budget[0]>128 or depth>12:raise ValueError('Explain one smaller modal query.')
  if not isinstance(x,dict):raise ValueError('Use a Boolean query.')
  op=x.get('op')
  if op=='atom':
   if x.get('name') not in ids:raise ValueError('Unknown world proposition.')
   seen.add(x['name']);return ids[x['name']]
  if op=='not':return -expr(x['arg'],depth+1)
  if op=='const':
   if type(x.get('value')) is not bool:raise ValueError('Use a Boolean constant.')
   serial[0]+=1;k=serial[0];cnf.append([k if x['value'] else -k]);return k
  if op not in ('and','or','implies','iff'):raise ValueError('Supported world operators: atom, not, and, or, implies, iff.')
  a,b=expr(x['left'],depth+1),expr(x['right'],depth+1);serial[0]+=1;k=serial[0]
  if op=='and':cnf.extend([[-k,a],[-k,b],[k,-a,-b]])
  if op=='or':cnf.extend([[k,-a],[k,-b],[-k,a,b]])
  if op=='implies':cnf.extend([[k,a],[k,-b],[-k,-a,b]])
  if op=='iff':cnf.extend([[-k,-a,b],[-k,a,-b],[k,-a,-b],[k,a,b]])
  return k
 modal=e.get('op');body=e.get('arg')
 if modal not in ('box','diamond'):raise ValueError('Choose box (all worlds) or diamond (some world).')
 k=expr(body)
 consistent=satisfiable(cnf)
 if not consistent:return dict(status='inconsistent',holds=None,detail='No admissible world; a vacuous universal is not credited.')
 holds=not satisfiable(cnf+[[-k]]) if modal=='box' else satisfiable(cnf+[[k]])
 return dict(status='checked',holds=holds,operator=modal,scope=scope,propositions=sorted(seen),constraints=len(cnf),semantics='Boolean/Horn admissible worlds; universal accessibility; not arbitrary HOL')
def state(s,accepted):
 from . import learner
 visited=set()
 for i,c in enumerate(accepted):
  checked=learner.context(c,accepted[:i],s)
  if checked['grounded']:visited.update((p['id'],p['positive']) for p in c['conclusions']+checked['roots'])
 return dict(representation='symbolic clauses',initial_learner_state='All valuations permitted; scenario givens are available but unvisited',givens=[p for p,n in s['nodes'].items() if n.get('fact')],rules=s['rules'],learner_values=[dict(id=p,positive=v,source='verified learner step or its explicitly connected support') for p,v in sorted(visited)],hypotheses_do_not_filter_worlds=True)
